function formatTimeShort(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [isLongTransition, setIsLongTransition] = useState(false);
  const [isMediumTransition, setIsMediumTransition] = useState(false);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill'} | null>(null);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
  }, [settings.sound, settings.vibration]);

  useEffect(() => {
    const timer = setTimeout(() => setScreen('difficulty'), 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setPoints(Storage.getPoints());
  }, [screen]);

  // Update theme color meta tag to match background to prevent white/black bars in some contexts
  useEffect(() => {
      const meta = document.querySelector('meta[name="theme-color"]');
      if (meta) {
          meta.setAttribute('content', '#fafaf9'); 
      }
  }, [selectedBackgroundId]);

  const transitionTo = (nextScreen: Screen, type: 'short' | 'medium' | 'long' = 'short') => {
      if (type === 'long') setIsLongTransition(true);
      else if (type === 'medium') setIsMediumTransition(true);
      else { setIsLongTransition(false); setIsMediumTransition(false); }

      setIsTransitioning(true);
      setTimeout(() => {
          setScreen(nextScreen);
          setPoints(Storage.getPoints());
          setIsTransitioning(false);
      }, type === 'long' ? 1000 : (type === 'medium' ? 500 : 300));
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    transitionTo('levels', 'medium');
  };

  const handleLevelBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleGameBack = () => { sounds.playClick(); transitionTo('levels', 'medium'); };
  const handleReturnToMenu = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleStoreBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };

  const handleLevelSelect = (levelId: number) => {
    sounds.playClick();
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setSelectedLevel(levelId);
        transitionTo('game', 'medium');
    }
  };

  const confirmReplay = () => {
      sounds.playClick();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          transitionTo('game', 'medium');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill') => {
      if (item.locked) return;
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      sounds.playClick();
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills([...purchasedSkills, purchaseCandidate.id]);
             }
          }
          setPoints(Storage.getPoints());
      } else {
          alert("Not enough Rhombuses!");
      }
      setPurchaseCandidate(null);
  };

  // Determine Background Logic
  let activeBackgroundClass = "bg-paper"; // Default for Menu, Levels, Store, Settings

  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50";
  } else if (screen === 'game') {
      // ONLY show custom background in Game
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
              // Ensure animation is slow for gameplay
              if (activeBackgroundClass.includes('animate-gradient')) {
                  activeBackgroundClass = activeBackgroundClass.replace('animate-gradient', 'animate-gradient-slow');
              }
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  // Dynamic transition classes
  const transitionDuration = isLongTransition ? 'duration-1000' : (isMediumTransition ? 'duration-500' : 'duration-300');
  // Fade background out and in for long and medium transitions to avoid flashes on navigation
  const bgOpacity = (isTransitioning && (isLongTransition || isMediumTransition)) ? 'opacity-0' : 'opacity-100';

  // --- Main Render with Strict Layer Architecture ---
  return (
      <>
          {/* LAYER 1: Background - Fixed, Full Screen, Z-Index 0 */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out bg-stone-50 ${activeBackgroundClass} ${transitionDuration} ${bgOpacity}`} 
            style={{ width: '100%', height: '100%' }}
          />

          {/* LAYER 2: UI - Relative, Z-Index 1, Padding for Safe Area */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-stone-800 overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <div className={`w-full h-full flex flex-col ${
                isTransitioning 
                   ? (isLongTransition ? 'animate-fade-out-long' : (isMediumTransition ? 'animate-fade-out-medium' : 'animate-fade-out')) 
                   : (isLongTransition ? 'animate-fade-in-long' : (isMediumTransition ? 'animate-fade-in-medium' : 'animate-fade-in'))
            }`}>

                {/* SPLASH */}
                {screen === 'splash' && (
                    <div className="flex-1 flex flex-col items-center justify-center">
                      <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                          <div className="grid grid-cols-2 gap-1">
                              <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                              <div className="w-3 h-3 bg-white rounded-sm"></div>
                              <div className="w-3 h-3 bg-white rounded-sm"></div>
                              <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                          </div>
                      </div>
                      <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
                      <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
                    </div>
                )}

                {/* MAIN MENU / DIFFICULTY */}
                {screen === 'difficulty' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                         {/* Scrollable Area - Top Padding is constant since Env is handled by wrapper */}
                         <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                              <div className="w-full max-w-md flex justify-between items-center mb-8 mt-2 shrink-0">
                                  <div>
                                      <h1 className="text-2xl font-bold">Select Mode</h1>
                                      <p className="text-stone-400 text-sm">Choose your difficulty</p>
                                  </div>
                                  <div className="flex gap-2">
                                      <div className="flex items-center gap-1 bg-white px-3 py-2 rounded-full shadow-sm border border-stone-100">
                                          <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                          <span className="text-sm font-bold text-stone-700">{points}</span>
                                      </div>
                                      <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                                          <Icons.Settings className="w-6 h-6 text-stone-600" />
                                      </button>
                                  </div>
                              </div>

                              <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-6 shrink-0">
                                  {Object.values(Difficulty).map((diff) => {
                                      const completed = Storage.getCompletedCount(diff);
                                      const maxLevels = getLevelCount(diff);
                                      return (
                                          <button key={diff} onClick={() => handleDifficultySelect(diff)} className="bg-white p-5 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-1 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left">
                                              <span className="text-lg font-bold text-stone-700">{diff}</span>
                                              <span className="text-sm text-stone-400 font-medium tracking-wide">{completed} / {maxLevels}</span>
                                              <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                                                  <div className="h-full bg-stone-800" style={{ width: `${Math.min((completed/maxLevels)*100, 100)}%` }}></div>
                                              </div>
                                          </button>
                                      )
                                  })}
                              </div>

                              <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                                  <button onClick={() => { sounds.playClick(); transitionTo('store', 'medium'); }} className="w-full p-4 bg-gradient-to-r from-stone-800 to-stone-700 text-white rounded-2xl shadow-lg flex items-center justify-center gap-3 active:scale-95 transition">
                                      <Icons.Store className="w-5 h-5" /> <span className="font-bold tracking-wide">Store</span>
                                  </button>
                                  <button className="w-full p-4 bg-white border border-blue-200 text-blue-600 rounded-2xl shadow-sm flex items-center justify-center gap-3 active:scale-95 transition hover:bg-blue-50">
                                      <Icons.Video className="w-5 h-5" /> <span className="font-medium">Watch an ad and get 10 <Icons.Diamond className="w-4 h-4 fill-current inline mb-0.5" /></span>
                                  </button>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* LEVELS */}
                {screen === 'levels' && selectedDifficulty && (() => {
                    // Calculate global best time logic for both Header and Grid
                    const levelCount = getLevelCount(selectedDifficulty);
                    const allLevels = Array.from({ length: levelCount }, (_, i) => i + 1);

                    let globalBest = Infinity;
                    allLevels.forEach(l => {
                        const p = Storage.getLevelProgress(selectedDifficulty, l);
                        if (p?.bestTime !== undefined && p.bestTime < globalBest) {
                            globalBest = p.bestTime;
                        }
                    });
                    const hasGlobalBest = globalBest !== Infinity;

                    return (
                        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                            <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                            <button onClick={handleLevelBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                            <div className="w-full text-center mt-2 pointer-events-none">
                                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                                <p className="text-xs text-stone-400 uppercase tracking-widest mb-1">Select Level</p>
                                {hasGlobalBest && (
                                    <div className="flex flex-col items-center animate-fade-in mt-3">
                                        <span className="text-[8px] font-black text-amber-500 tracking-widest uppercase mb-px opacity-90">Best</span>
                                        <span className="text-lg font-medium text-stone-700 tabular-nums leading-none">{formatTimeShort(globalBest)}</span>
                                    </div>
                                )}
                            </div>
                            <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="absolute right-6 top-[20px] p-2 rounded-full hover:bg-stone-200 -mr-2"><Icons.Settings className="w-6 h-6 text-stone-600" /></button>
                            </div>

                            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                                <div className="w-full max-w-md grid grid-cols-5 gap-3">
                                    {allLevels.map((lvl) => {
                                            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
                                            const isCompleted = progress?.status === 'completed';
                                            const isInProgress = progress?.status === 'in-progress';
                                            const bestTime = progress?.bestTime;
                                            const isGlobalBest = hasGlobalBest && bestTime !== undefined && bestTime === globalBest;

                                            return (
                                                <button key={lvl} onClick={() => handleLevelSelect(lvl)} className={`aspect-square rounded-xl relative transition-all active:scale-90 ${isCompleted ? 'bg-stone-100 text-stone-300 border border-stone-100 ring-1 ring-inset ring-stone-900/5' : isInProgress ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}`}>
                                                    <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{lvl}</span></div>
                                                    {bestTime ? (
                                                        isGlobalBest ? (
                                                            <>
                                                                <div className="absolute top-1.5 inset-x-0 flex justify-center">
                                                                    <span className="text-[8px] font-black text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                                                                </div>
                                                                <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                                                                    <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                                                                </div>
                                                            </>
                                                        ) : (
                                                            <div className="absolute bottom-1.5 inset-x-0 text-center">
                                                                <span className="text-[10px] text-stone-400 font-bold tracking-tight block">{formatTimeShort(bestTime)}</span>
                                                            </div>
                                                        )
                                                    ) : (
                                                        isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2 left-1/2 -translate-x-1/2"></div>
                                                    )}
                                                </button>
                                            );
                                    })}
                                </div>
                                <div className="h-safe-bottom w-full shrink-0" />
                            </div>
                        </div>
                    );
                })()}

                {/* STORE */}
                {screen === 'store' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                         <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                              <button onClick={handleStoreBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                              <div className="w-full text-center mt-2 pointer-events-none"><h1 className="text-xl font-bold text-stone-800">Store</h1></div>
                              <div className="absolute right-6 top-[20px] flex items-center gap-1 bg-white px-3 py-2 rounded-full shadow-sm border border-stone-100">
                                  <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                  <span className="text-sm font-bold text-stone-700">{points}</span>
                              </div>
                         </div>
                         <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                              <div className="w-full max-w-md space-y-8">
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Backgrounds</h2>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 ml-1">Static</h3>
                                          <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : (bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : '')} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                                  <span className="text-sm font-bold text-stone-900 leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 ml-1">Dynamic</h3>
                                          <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                                  <span className="text-sm font-bold text-stone-900 leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{bg.name}</span>
