// Modals
interface PurchaseModalProps {
    item: { id: string; name: string; cost: number };
    onConfirm: () => void;
    onCancel: () => void;
}

const PurchaseModal: React.FC<PurchaseModalProps> = ({ item, onConfirm, onCancel }) => {
    const [isClosing, setIsClosing] = useState(false);
    const handleAction = (action: () => void) => {
        sounds.playClick();
        setIsClosing(true);
        setTimeout(() => action(), 300);
    };
    return (
        <div 
            className={`fixed inset-0 z-[110] flex items-center justify-center bg-black/20 backdrop-blur-sm px-4 ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} 
            onClick={() => handleAction(onCancel)}
        >
            <div className={`bg-white p-6 rounded-3xl shadow-2xl w-full max-w-xs text-center ${isClosing ? '' : 'animate-pop'}`} onClick={e => e.stopPropagation()}>
                <h3 className="text-xl font-bold text-stone-800 mb-2">Unlock {item.name}?</h3>
                <div className="text-stone-600 font-medium mb-1 flex items-center justify-center gap-1">
                    Buy this item for <span className="text-stone-800 font-bold">{item.cost}</span> <span className="text-blue-500"><Icons.Diamond className="w-4 h-4 fill-current" /></span>?
                </div>
                <div className="flex gap-3 mt-6">
                    <button onClick={() => handleAction(onCancel)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-bold active:scale-95 transition">No</button>
                    <button onClick={() => handleAction(onConfirm)} className="flex-1 py-3 text-white bg-stone-800 rounded-xl font-bold shadow-lg active:scale-95 transition">Yes</button>
                </div>
            </div>
        </div>
