class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    private vibrate(pattern: number | number[]) {
        if (!this.vibrationEnabled) return;
        if (typeof navigator !== 'undefined' && navigator.vibrate) {
            try {
                navigator.vibrate(pattern);
            } catch (e) {
                // Ignore vibration errors or lack of support
            }
        }
    }

    private playTone(freq: number, type: 'sine' | 'triangle', duration: number, volume: number = 0.05) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = type;
            osc.frequency.setValueAtTime(freq, ctx.currentTime);

            const t = ctx.currentTime;
            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(volume, t + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, t + duration);

            osc.start(t);
            osc.stop(t + duration + 0.1);
        } catch (e) {
            // Ignore audio errors
        }
    }

    // Soft tick for standard UI buttons
    playClick() {
        this.vibrate(10); // Crisp click
        this.playTone(800, 'sine', 0.05, 0.2); // Increased from 0.03
    }

    // Softer tap for grid selection
    playTap() {
        this.vibrate(4); // Very subtle
        this.playTone(600, 'triangle', 0.05, 0.15); // Increased from 0.02
    }

    // Pentatonic scale for number inputs (C Major Pentatonic: C, D, E, G, A)
    // 1-9 maps to ascending pitches
    playNumber(num: number) {
        this.vibrate(8); // Distinct input feel

        // Frequencies for C5 Pentatonic scale extended
        const freqs = [
            523.25, // 1: C5
            587.33, // 2: D5
            659.25, // 3: E5
            783.99, // 4: G5
            880.00, // 5: A5
            1046.50, // 6: C6
            1174.66, // 7: D6
            1318.51, // 8: E6
            1567.98  // 9: G6
        ];

        const freq = freqs[num - 1] || 440;
        this.playTone(freq, 'sine', 0.15, 0.3); // Increased from 0.04
    }

    playPop() {
        this.vibrate(15); // Slightly heavier for actions
        this.playTone(400, 'sine', 0.1, 0.3); // Increased from 0.05
    }

    // New sound for Auto/Zap - high tech slide
    playZap() {
        this.vibrate(12);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            const t = ctx.currentTime;

            // Slide frequency from 1200Hz down to 600Hz rapidly
            osc.frequency.setValueAtTime(1200, t);
            osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);

            // Envelope
            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.25, t + 0.01); // Increased from 0.04
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);

            osc.start(t);
            osc.stop(t + 0.2);
        } catch (e) {
            // Ignore audio errors
        }
    }

    playWin() {
        this.vibrate([50, 50, 50, 50, 100]); // Celebration pattern

        if (!this.soundEnabled) return;
        const ctx = this.getCtx();
        // const t = ctx.currentTime; // Not used directly in loop below, relying on setTimeout
        const notes = [523.25, 659.25, 783.99, 1046.50]; // C Major Chord

        notes.forEach((freq, i) => {
            setTimeout(() => {
                this.playTone(freq, 'sine', 0.4, 0.3); // Increased from 0.05
            }, i * 100);
        });
    }
}

