function formatTimeShort(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [isLongTransition, setIsLongTransition] = useState(false);
  const [isMediumTransition, setIsMediumTransition] = useState(false);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill'} | null>(null);
  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
  }, [settings.sound, settings.vibration]);

  useEffect(() => {
    const timer = setTimeout(() => setScreen('difficulty'), 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setPoints(Storage.getPoints());
  }, [screen]);

  // Update theme color meta tag to match background to prevent white/black bars in some contexts
  useEffect(() => {
      const meta = document.querySelector('meta[name="theme-color"]');
      if (meta) {
          meta.setAttribute('content', '#fafaf9'); 
      }
  }, [selectedBackgroundId]);

  const transitionTo = (nextScreen: Screen, type: 'short' | 'medium' | 'long' = 'short') => {
      if (type === 'long') setIsLongTransition(true);
      else if (type === 'medium') setIsMediumTransition(true);
      else { setIsLongTransition(false); setIsMediumTransition(false); }

      setIsTransitioning(true);
      setTimeout(() => {
          setScreen(nextScreen);
          setPoints(Storage.getPoints());
          setIsTransitioning(false);
      }, type === 'long' ? 1000 : (type === 'medium' ? 500 : 300));
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    transitionTo('levels', 'medium');
  };

  const handleLevelBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleGameBack = () => { sounds.playClick(); transitionTo('levels', 'medium'); };
  const handleReturnToMenu = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleStoreBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };

  const handleLevelSelect = (levelId: number) => {
    sounds.playClick();
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setSelectedLevel(levelId);
        transitionTo('game', 'medium');
    }
  };

  const confirmReplay = () => {
      sounds.playClick();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          transitionTo('game', 'medium');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill') => {
      if (item.locked) return;
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      sounds.playClick();
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills([...purchasedSkills, purchaseCandidate.id]);
             }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          // Not enough points
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        sounds.playClick();
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(10);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleGoPlay = () => {
      sounds.playClick();
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          transitionTo('difficulty', 'medium');
      }
  };

  // Determine Background Logic
  let activeBackgroundClass = "bg-paper"; // Default for Menu, Levels, Store, Settings

  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50";
  } else if (screen === 'game') {
      // ONLY show custom background in Game
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
              // Ensure animation is slow for gameplay
              if (activeBackgroundClass.includes('animate-gradient')) {
                  activeBackgroundClass = activeBackgroundClass.replace('animate-gradient', 'animate-gradient-slow');
              }
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  // Dynamic transition classes
  const transitionDuration = isLongTransition ? 'duration-1000' : (isMediumTransition ? 'duration-500' : 'duration-300');
  // Fade background out and in for long and medium transitions to avoid flashes on navigation
  const bgOpacity = (isTransitioning && (isLongTransition || isMediumTransition)) ? 'opacity-0' : 'opacity-100';

  // --- Main Render with Strict Layer Architecture ---
  return (
      <>
          {/* LAYER 1: Background - Fixed, Full Screen, Z-Index 0 */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out bg-stone-50 ${activeBackgroundClass} ${transitionDuration} ${bgOpacity}`} 
            style={{ width: '100%', height: '100%' }}
          />

          {/* LAYER 2: UI - Relative, Z-Index 1, Padding for Safe Area */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-stone-800 overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <div className={`w-full h-full flex flex-col ${
                isTransitioning 
                   ? (isLongTransition ? 'animate-fade-out-long' : (isMediumTransition ? 'animate-fade-out-medium' : 'animate-fade-out')) 
                   : (isLongTransition ? 'animate-fade-in-long' : (isMediumTransition ? 'animate-fade-in-medium' : 'animate-fade-in'))
            }`}>

                {/* SPLASH */}
                {screen === 'splash' && (
                    <div className="flex-1 flex flex-col items-center justify-center">
                      <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                          <div className="grid grid-cols-2 gap-1">
                              <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                              <div className="w-3 h-3 bg-white rounded-sm"></div>
                              <div className="w-3 h-3 bg-white rounded-sm"></div>
                              <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                          </div>
                      </div>
                      <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
                      <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
                    </div>
                )}

                {/* MAIN MENU / DIFFICULTY */}
                {screen === 'difficulty' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                         {/* Scrollable Area - Top Padding is constant since Env is handled by wrapper */}
                         <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                              <div className="w-full max-w-md flex justify-between items-center mb-8 mt-2 shrink-0">
                                  <div>
                                      <h1 className="text-2xl font-bold">Select Mode</h1>
                                      <p className="text-stone-400 text-sm">Choose your difficulty</p>
                                  </div>
                                  <div className="flex gap-2">
                                      <div className="flex items-center gap-1 bg-white px-3 py-2 rounded-full shadow-sm border border-stone-100">
                                          <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                          <span className="text-sm font-bold text-stone-700">{points}</span>
                                      </div>
                                      <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                                          <Icons.Settings className="w-6 h-6 text-stone-600" />
                                      </button>
                                  </div>
                              </div>

                              <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-6 shrink-0">
                                  {Object.values(Difficulty).map((diff) => {
                                      const completed = Storage.getCompletedCount(diff);
                                      const maxLevels = getLevelCount(diff);
                                      const points = getDifficultyPoints(diff);
                                      return (
                                          <button key={diff} onClick={() => handleDifficultySelect(diff)} className="bg-white p-5 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-1 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left relative overflow-hidden">
                                              <div className="w-full flex justify-between items-start">
                                                  <span className="text-lg font-bold text-stone-700 leading-tight">{diff}</span>
                                                  <div className="flex items-center gap-1 bg-blue-50 px-2 py-1 rounded-lg ml-2 shrink-0">
                                                      <span className="text-xs font-bold text-blue-600">+{points}</span>
                                                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                                  </div>
                                              </div>
                                              <span className="text-sm text-stone-400 font-medium tracking-wide mt-1">{completed} / {maxLevels}</span>
                                              <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                                                  <div className="h-full bg-stone-800" style={{ width: `${Math.min((completed/maxLevels)*100, 100)}%` }}></div>
                                              </div>
                                          </button>
                                      )
                                  })}
                              </div>

                              <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                                  <button onClick={() => { sounds.playClick(); transitionTo('store', 'medium'); }} className="w-full p-4 bg-gradient-to-r from-stone-800 to-stone-700 text-white rounded-2xl shadow-lg flex items-center justify-center gap-3 active:scale-95 transition">
                                      <Icons.Store className="w-5 h-5" /> <span className="font-bold tracking-wide">Store</span>
                                  </button>
                                  <button onClick={handleWatchAd} className="w-full p-4 bg-white border-2 border-blue-100 text-blue-500 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:bg-blue-50">
                                      <Icons.Video className="w-5 h-5" /> <span className="font-bold text-sm">Watch an ad and get 10 <Icons.Diamond className="w-3 h-3 fill-current inline mb-0.5" /></span>
                                  </button>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* LEVELS */}
                {screen === 'levels' && selectedDifficulty && (() => {
                    // Calculate global best time logic for both Header and Grid
                    const levelCount = getLevelCount(selectedDifficulty);
                    const allLevels = Array.from({ length: levelCount }, (_, i) => i + 1);

                    let globalBest = Infinity;
                    allLevels.forEach(l => {
                        const p = Storage.getLevelProgress(selectedDifficulty, l);
                        if (p?.bestTime !== undefined && p.bestTime < globalBest) {
                            globalBest = p.bestTime;
                        }
                    });
                    const hasGlobalBest = globalBest !== Infinity;

                    return (
                        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                            <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                            <button onClick={handleLevelBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                            <div className="w-full text-center mt-2 pointer-events-none">
                                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                                <p className="text-xs text-stone-400 uppercase tracking-widest mb-1">Select Level</p>
                                {hasGlobalBest && (
                                    <div className="flex flex-col items-center animate-fade-in mt-3">
                                        <span className="text-[8px] font-black text-amber-500 tracking-widest uppercase mb-px opacity-90">Best</span>
                                        <span className="text-lg font-medium text-stone-700 tabular-nums leading-none">{formatTimeShort(globalBest)}</span>
                                    </div>
                                )}
                            </div>
                            <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="absolute right-6 top-[20px] p-2 rounded-full hover:bg-stone-200 -mr-2"><Icons.Settings className="w-6 h-6 text-stone-600" /></button>
                            </div>

                            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                                <div className="w-full max-w-md grid grid-cols-5 gap-3">
                                    {allLevels.map((lvl) => {
                                            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
                                            const isCompleted = progress?.status === 'completed';
                                            const isInProgress = progress?.status === 'in-progress';
                                            const bestTime = progress?.bestTime;
                                            const isGlobalBest = hasGlobalBest && bestTime !== undefined && bestTime === globalBest;

                                            return (
                                                <button key={lvl} onClick={() => handleLevelSelect(lvl)} className={`aspect-square rounded-xl relative transition-all active:scale-90 ${isCompleted ? 'bg-stone-100 text-stone-300 border border-stone-100 ring-1 ring-inset ring-stone-900/5' : isInProgress ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}`}>
                                                    <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{lvl}</span></div>
                                                    {bestTime ? (
                                                        isGlobalBest ? (
                                                            <>
                                                                <div className="absolute top-1.5 inset-x-0 flex justify-center">
                                                                    <span className="text-[8px] font-black text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                                                                </div>
                                                                <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                                                                    <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                                                                </div>
                                                            </>
                                                        ) : (
                                                            <div className="absolute bottom-1.5 inset-x-0 text-center">
                                                                <span className="text-[10px] text-stone-400 font-bold tracking-tight block">{formatTimeShort(bestTime)}</span>
                                                            </div>
                                                        )
                                                    ) : null}
                                                </button>
                                            );
                                    })}
                                </div>
                                <div className="h-safe-bottom w-full shrink-0" />
                            </div>
                        </div>
                    );
                })()}

                {/* STORE */}
                {screen === 'store' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                         <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                              <button onClick={handleStoreBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                              <div className="w-full text-center mt-2 pointer-events-none"><h1 className="text-xl font-bold text-stone-800">Store</h1></div>
                              <div className="absolute right-6 top-[20px] flex items-center gap-1 bg-white px-3 py-2 rounded-full shadow-sm border border-stone-100">
                                  <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                  <span className="text-sm font-bold text-stone-700">{points}</span>
                              </div>
                         </div>
                         <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                              <div className="w-full max-w-md space-y-8">
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Backgrounds</h2>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 ml-1">Static</h3>
                                          <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : (bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : '')} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                                  <span className="text-sm font-bold text-stone-900 leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 ml-1">Dynamic</h3>
                                          <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                                  <span className="text-sm font-bold text-stone-900 leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                  </div>
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Numbers</h2>
                                      <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                                          const isPurchased = purchasedNumberColors.includes(num.id);
                                          const isSelected = selectedNumberColorId === num.id;
                                          return (
                                              <div key={num.id} className="flex flex-col items-center gap-1">
                                                  <button onClick={() => isPurchased ? handleSelectNumberColor(num.id) : initiatePurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-white ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                      <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                                          <span className={`text-3xl font-bold leading-none ${num.uiClass}`}>5</span>
                                                      </div>
                                                      {!isPurchased && (
                                                          <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                              <span className="text-sm font-bold text-stone-900 leading-none">{num.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{num.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Skills</h2>
                                      <div className="grid grid-cols-5 gap-2">{SKILLS.map(skill => {
                                          const isPurchased = purchasedSkills.includes(skill.id);
                                          const isLocked = skill.locked;
                                          return (
                                              <div key={skill.id} className="flex flex-col items-center gap-1">
                                                  <button onClick={() => !isPurchased && !isLocked ? initiatePurchase(skill, 'skill') : null} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isPurchased ? 'bg-white ring-2 ring-inset ring-blue-500' : 'bg-white active:scale-95'} ${isLocked ? 'cursor-not-allowed opacity-60 bg-stone-100' : ''}`}>
                                                      <div className={`flex items-center justify-center w-full h-full ${!isPurchased && !isLocked ? 'pb-4' : ''}`}>
                                                          <skill.icon className={`w-8 h-8 ${skill.class}`} />
                                                      </div>
                                                      {!isPurchased && !isLocked && (
                                                          <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                              <span className="text-sm font-bold text-stone-900 leading-none">{skill.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{skill.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* GAME */}
                {screen === 'game' && selectedDifficulty && selectedLevel && (
                    <div className="flex-1 w-full flex flex-col overflow-hidden" style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 16px)' }}>
                        <SudokuGame 
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {}} 
                            onSettingsOpen={() => { sounds.playClick(); setShowSettings(true); }}
                            onNextLevel={() => { sounds.playClick(); const max = getLevelCount(selectedDifficulty); if (selectedLevel < max) { setSelectedLevel(selectedLevel + 1); setPoints(Storage.getPoints()); } else transitionTo('levels'); }}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={purchasedSkills}
                        />
                    </div>
                )}

            </div>
          </div>

          {/* Global Modals - Z-Index 100+ */}
          {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
          {purchaseCandidate && <PurchaseModal item={purchaseCandidate} onConfirm={confirmPurchase} onCancel={() => { sounds.playClick(); setPurchaseCandidate(null); }} />}
          {replayLevelId && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in"><div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop"><h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3><p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p><div className="flex gap-3"><button onClick={() => { sounds.playClick(); setReplayLevelId(null); }} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button><button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button></div></div></div>}
          {showNotEnoughPoints && <NotEnoughPointsModal onClose={() => { sounds.playClick(); setShowNotEnoughPoints(false); }} onWatchAd={handleWatchAd} onGoPlay={handleGoPlay} />}
          {isWatchingAd && <AdOverlay />}

      </>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';
import { sounds } from './utils/sound';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store';

// Define Level Counts
const getLevelCount = (diff: Difficulty) => {
    switch (diff) {
        case Difficulty.Intense: return 20;
        case Difficulty.Impossible: return 10;
        default: return 100;
    }
};

const getDifficultyPoints = (diff: Difficulty) => {
    switch(diff) {
        case Difficulty.SuperEasy: return 5;
        case Difficulty.Easy: return 10;
        case Difficulty.Normal: return 15;
        case Difficulty.Hard: return 20;
        case Difficulty.Intense: return 30;
        case Difficulty.Impossible: return 50;
        default: return 0;
    }
};

// Define Store Items
const STATIC_BACKGROUNDS = [
    { id: 'bg-default', name: 'Default', cost: 0, class: 'bg-paper' },
    { id: 'bg-dawn', name: 'Dawn', cost: 100, class: 'bg-gradient-to-br from-orange-50 to-rose-50' },
    { id: 'bg-ocean', name: 'Ocean', cost: 100, class: 'bg-gradient-to-br from-sky-50 to-cyan-50' },
    { id: 'bg-forest', name: 'Forest', cost: 100, class: 'bg-gradient-to-br from-emerald-50 to-green-50' },
    { id: 'bg-dusk', name: 'Dusk', cost: 100, class: 'bg-gradient-to-br from-violet-50 to-purple-50' },
];

const DYNAMIC_BACKGROUNDS = [
    { id: 'bg-prism', name: 'Prism', cost: 150, class: 'bg-gradient-to-tr from-violet-300/40 via-purple-50/50 to-lime-300/40 bg-[length:400%_400%] animate-gradient' },
    { id: 'bg-horizon', name: 'Horizon', cost: 150, class: 'bg-gradient-to-bl from-sky-300/40 via-indigo-50/50 to-orange-300/40 bg-[length:400%_400%] animate-gradient' },
    { id: 'bg-coral', name: 'Coral', cost: 150, class: 'bg-gradient-to-br from-teal-300/40 via-cyan-50/50 to-pink-300/40 bg-[length:400%_400%] animate-gradient' },
    { id: 'bg-orbit', name: 'Orbit', cost: 150, class: 'bg-gradient-to-tl from-indigo-300/40 via-rose-50/50 to-amber-300/40 bg-[length:400%_400%] animate-gradient' },
    { id: 'bg-flux', name: 'Flux', cost: 150, class: 'bg-gradient-to-r from-cyan-300/40 via-sky-50/50 to-red-300/40 bg-[length:400%_400%] animate-gradient' },
];

const NUMBER_COLORS = [
    { id: 'num-default', name: 'Default', cost: 0, class: 'text-blue-600', uiClass: 'text-blue-600' },
    { id: 'num-purple', name: 'Purple', cost: 100, class: 'text-purple-600', uiClass: 'text-purple-600' },
    { id: 'num-teal', name: 'Teal', cost: 100, class: 'text-teal-600', uiClass: 'text-teal-600' },
    { id: 'num-shine', name: 'Gold', cost: 500, class: 'text-shine-gold', uiClass: 'text-shine-gold' },
    { id: 'num-rgb', name: 'Diamond', cost: 500, class: 'text-shine-diamond', uiClass: 'text-shine-diamond' },
];

const SKILLS = [
    { id: 'skill-auto', name: 'Auto', cost: 750, icon: Icons.Auto, class: 'text-amber-500' },
    { id: 'skill-ph1', name: 'Coming Soon', cost: 0, icon: Icons.Lock, class: 'text-stone-300', locked: true },
    { id: 'skill-ph2', name: 'Coming Soon', cost: 0, icon: Icons.Lock, class: 'text-stone-300', locked: true },
    { id: 'skill-ph3', name: 'Coming Soon', cost: 0, icon: Icons.Lock, class: 'text-stone-300', locked: true },
    { id: 'skill-ph4', name: 'Coming Soon', cost: 0, icon: Icons.Lock, class: 'text-stone-300', locked: true },
];

const ALL_BACKGROUNDS = [...STATIC_BACKGROUNDS, ...DYNAMIC_BACKGROUNDS];

// Modals
interface PurchaseModalProps {
    item: { id: string; name: string; cost: number };
    onConfirm: () => void;
    onCancel: () => void;
}

const PurchaseModal: React.FC<PurchaseModalProps> = ({ item, onConfirm, onCancel }) => {
    const [isClosing, setIsClosing] = useState(false);
    const handleAction = (action: () => void) => {
        sounds.playClick();
        setIsClosing(true);
        setTimeout(() => action(), 300);
    };
    return (
        <div 
            className={`fixed inset-0 z-[110] flex items-center justify-center bg-black/20 backdrop-blur-sm px-4 ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} 
            onClick={() => handleAction(onCancel)}
        >
            <div className={`bg-white p-6 rounded-3xl shadow-2xl w-full max-w-xs text-center ${isClosing ? '' : 'animate-pop'}`} onClick={e => e.stopPropagation()}>
                <h3 className="text-xl font-bold text-stone-800 mb-2">Unlock {item.name}?</h3>
                <div className="text-stone-600 font-medium mb-1 flex items-center justify-center gap-1">
                    Buy this item for <span className="text-stone-800 font-bold">{item.cost}</span> <span className="text-blue-500"><Icons.Diamond className="w-4 h-4 fill-current" /></span>?
                </div>
                <div className="flex gap-3 mt-6">
                    <button onClick={() => handleAction(onCancel)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-bold active:scale-95 transition">No</button>
                    <button onClick={() => handleAction(onConfirm)} className="flex-1 py-3 text-white bg-stone-800 rounded-xl font-bold shadow-lg active:scale-95 transition">Yes</button>
                </div>
            </div>
        </div>
    );
};

interface NotEnoughPointsModalProps {
    onClose: () => void;
    onWatchAd: () => void;
    onGoPlay: () => void;
}

const NotEnoughPointsModal: React.FC<NotEnoughPointsModalProps> = ({ onClose, onWatchAd, onGoPlay }) => {
    const [isClosing, setIsClosing] = useState(false);
    const handleAction = (action: () => void) => {
        sounds.playClick();
        setIsClosing(true);
        setTimeout(() => action(), 300);
    };

    return (
        <div className={`fixed inset-0 z-[120] flex items-center justify-center bg-black/20 backdrop-blur-sm px-4 ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={() => handleAction(onClose)}>
            <div className={`bg-white p-6 rounded-3xl shadow-2xl w-full max-w-xs text-center relative ${isClosing ? '' : 'animate-pop'}`} onClick={e => e.stopPropagation()}>
                <button onClick={() => handleAction(onClose)} className="absolute right-4 top-4 p-2 bg-stone-100 rounded-full hover:bg-stone-200 text-stone-500 active:scale-95 transition">
                    <Icons.Close className="w-4 h-4" />
                </button>

                <div className="flex flex-col items-center justify-center gap-2 mb-8 mt-4">
                     <div className="text-lg font-bold text-stone-800 flex items-center gap-2">
                        Not enough <span className="text-blue-500"><Icons.Diamond className="w-5 h-5 fill-current" /></span>
                     </div>
                </div>

                <div className="flex flex-col gap-3">
                     <button onClick={() => handleAction(onWatchAd)} className="w-full p-4 bg-white border-2 border-blue-100 text-blue-500 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:bg-blue-50">
                        <Icons.Video className="w-5 h-5" /> 
                        <span className="font-bold text-sm">Watch an ad and get 10 <Icons.Diamond className="w-3 h-3 fill-current inline mb-0.5" /></span>
                     </button>

                     <button onClick={() => handleAction(onGoPlay)} className="w-full py-4 text-stone-600 bg-stone-100 rounded-2xl font-bold active:scale-95 transition hover:bg-stone-200">
                        Go play
                     </button>
                </div>
            </div>
        </div>
    );
};

const AdOverlay: React.FC = () => (
    <div className="fixed inset-0 z-[150] bg-black flex flex-col items-center justify-center text-white animate-fade-in">
        <div className="absolute top-8 right-8 text-stone-500 font-mono text-xs">ADVERTISEMENT</div>
        <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-8"></div>
        <h2 className="text-2xl font-bold tracking-widest">ADVERTISEMENT</h2>
        <p className="text-stone-400 mt-2 text-sm">Thanks for supporting us!</p>
    </div>
);

interface SettingsModalProps {
    settings: AppSettings;
    onToggle: (key: keyof AppSettings) => void;
    onReset: () => void;
    onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onToggle, onReset, onClose }) => {
    const [isClosing, setIsClosing] = useState(false);
    const handleClose = () => {
        sounds.playClick();
        setIsClosing(true);
        setTimeout(() => onClose(), 300);
    };
    return (
        <div className={`fixed inset-0 z-[999] bg-black/40 backdrop-blur-md flex items-end sm:items-center justify-center ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={handleClose}>
            <div className={`bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl ${isClosing ? 'animate-slide-down' : 'animate-slide-up'}`} onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                    <button onClick={handleClose} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
                </div>
                <div className="space-y-4">
                    {['sound', 'vibration', 'highlight'].map((key) => (
                         <div key={key} className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                            <div className="flex items-center gap-3 text-stone-700 capitalize">
                                {key === 'sound' && <Icons.Sound className="w-5 h-5" />}
                                {key === 'vibration' && <Icons.Vibration className="w-5 h-5" />}
                                {key === 'highlight' && <Icons.Eye className="w-5 h-5" />}
                                <span>{key === 'highlight' ? 'Highlight Areas' : key}</span>
                            </div>
                            <button onClick={() => onToggle(key as keyof AppSettings)} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings[key as keyof AppSettings] ? 'bg-green-500' : 'bg-stone-300'}`}>
                                <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings[key as keyof AppSettings] ? 'translate-x-5' : 'translate-x-0'}`}></div>
                            </button>
                        </div>
                    ))}
                </div>
                <div className="mt-8 pt-6 border-t border-stone-100">
                    <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                        <Icons.Trash className="w-5 h-5" /> Reset All Progress
                    </button>
                </div>
            </div>
        </div>
    );
};

function formatTimeShort(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [isLongTransition, setIsLongTransition] = useState(false);
  const [isMediumTransition, setIsMediumTransition] = useState(false);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill'} | null>(null);
  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
  }, [settings.sound, settings.vibration]);

  useEffect(() => {
    const timer = setTimeout(() => setScreen('difficulty'), 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setPoints(Storage.getPoints());
  }, [screen]);

  // Update theme color meta tag to match background to prevent white/black bars in some contexts
  useEffect(() => {
      const meta = document.querySelector('meta[name="theme-color"]');
      if (meta) {
          meta.setAttribute('content', '#fafaf9'); 
      }
  }, [selectedBackgroundId]);

  const transitionTo = (nextScreen: Screen, type: 'short' | 'medium' | 'long' = 'short') => {
      if (type === 'long') setIsLongTransition(true);
      else if (type === 'medium') setIsMediumTransition(true);
      else { setIsLongTransition(false); setIsMediumTransition(false); }

      setIsTransitioning(true);
      setTimeout(() => {
          setScreen(nextScreen);
          setPoints(Storage.getPoints());
          setIsTransitioning(false);
      }, type === 'long' ? 1000 : (type === 'medium' ? 500 : 300));
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    transitionTo('levels', 'medium');
  };

  const handleLevelBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleGameBack = () => { sounds.playClick(); transitionTo('levels', 'medium'); };
  const handleReturnToMenu = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleStoreBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };

  const handleLevelSelect = (levelId: number) => {
    sounds.playClick();
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setSelectedLevel(levelId);
        transitionTo('game', 'medium');
    }
  };

  const confirmReplay = () => {
      sounds.playClick();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          transitionTo('game', 'medium');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill') => {
      if (item.locked) return;
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      sounds.playClick();
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills([...purchasedSkills, purchaseCandidate.id]);
             }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          // Not enough points
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        sounds.playClick();
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(10);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleGoPlay = () => {
      sounds.playClick();
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          transitionTo('difficulty', 'medium');
      }
  };

  // Determine Background Logic
  let activeBackgroundClass = "bg-paper"; // Default for Menu, Levels, Store, Settings

  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50";
  } else if (screen === 'game') {
      // ONLY show custom background in Game
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
              // Ensure animation is slow for gameplay
              if (activeBackgroundClass.includes('animate-gradient')) {
                  activeBackgroundClass = activeBackgroundClass.replace('animate-gradient', 'animate-gradient-slow');
              }
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  // Dynamic transition classes
  const transitionDuration = isLongTransition ? 'duration-1000' : (isMediumTransition ? 'duration-500' : 'duration-300');
  // Fade background out and in for long and medium transitions to avoid flashes on navigation
  const bgOpacity = (isTransitioning && (isLongTransition || isMediumTransition)) ? 'opacity-0' : 'opacity-100';

  // --- Main Render with Strict Layer Architecture ---
  return (
      <>
          {/* LAYER 1: Background - Fixed, Full Screen, Z-Index 0 */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out bg-stone-50 ${activeBackgroundClass} ${transitionDuration} ${bgOpacity}`} 
            style={{ width: '100%', height: '100%' }}
          />

          {/* LAYER 2: UI - Relative, Z-Index 1, Padding for Safe Area */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-stone-800 overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <div className={`w-full h-full flex flex-col ${
                isTransitioning 
                   ? (isLongTransition ? 'animate-fade-out-long' : (isMediumTransition ? 'animate-fade-out-medium' : 'animate-fade-out')) 
                   : (isLongTransition ? 'animate-fade-in-long' : (isMediumTransition ? 'animate-fade-in-medium' : 'animate-fade-in'))
            }`}>

                {/* SPLASH */}
                {screen === 'splash' && (
                    <div className="flex-1 flex flex-col items-center justify-center">
                      <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                          <div className="grid grid-cols-2 gap-1">
                              <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                              <div className="w-3 h-3 bg-white rounded-sm"></div>
                              <div className="w-3 h-3 bg-white rounded-sm"></div>
                              <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                          </div>
                      </div>
                      <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
                      <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
                    </div>
                )}

                {/* MAIN MENU / DIFFICULTY */}
                {screen === 'difficulty' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                         {/* Scrollable Area - Top Padding is constant since Env is handled by wrapper */}
                         <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                              <div className="w-full max-w-md flex justify-between items-center mb-8 mt-2 shrink-0">
                                  <div>
                                      <h1 className="text-2xl font-bold">Select Mode</h1>
                                      <p className="text-stone-400 text-sm">Choose your difficulty</p>
                                  </div>
                                  <div className="flex gap-2">
                                      <div className="flex items-center gap-1 bg-white px-3 py-2 rounded-full shadow-sm border border-stone-100">
                                          <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                          <span className="text-sm font-bold text-stone-700">{points}</span>
                                      </div>
                                      <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                                          <Icons.Settings className="w-6 h-6 text-stone-600" />
                                      </button>
                                  </div>
                              </div>

                              <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-6 shrink-0">
                                  {Object.values(Difficulty).map((diff) => {
                                      const completed = Storage.getCompletedCount(diff);
                                      const maxLevels = getLevelCount(diff);
                                      const points = getDifficultyPoints(diff);
                                      return (
                                          <button key={diff} onClick={() => handleDifficultySelect(diff)} className="bg-white p-5 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-1 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left relative overflow-hidden">
                                              <div className="w-full flex justify-between items-start">
                                                  <span className="text-lg font-bold text-stone-700 leading-tight">{diff}</span>
                                                  <div className="flex items-center gap-1 ml-2 shrink-0">
                                                      <span className="text-xs font-bold text-stone-900">+{points}</span>
                                                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                                  </div>
                                              </div>
                                              <span className="text-sm text-stone-400 font-medium tracking-wide mt-1">{completed} / {maxLevels}</span>
                                              <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                                                  <div className="h-full bg-stone-800" style={{ width: `${Math.min((completed/maxLevels)*100, 100)}%` }}></div>
                                              </div>
                                          </button>
                                      )
                                  })}
                              </div>

                              <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                                  <button onClick={() => { sounds.playClick(); transitionTo('store', 'medium'); }} className="w-full p-4 bg-gradient-to-r from-stone-800 to-stone-700 text-white rounded-2xl shadow-lg flex items-center justify-center gap-3 active:scale-95 transition">
                                      <Icons.Store className="w-5 h-5" /> <span className="font-bold tracking-wide">Store</span>
                                  </button>
                                  <button onClick={handleWatchAd} className="w-full p-4 bg-white border-2 border-blue-100 text-blue-500 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:bg-blue-50">
                                      <Icons.Video className="w-5 h-5" /> <span className="font-bold text-sm">Watch an ad and get 10 <Icons.Diamond className="w-3 h-3 fill-current inline mb-0.5" /></span>
                                  </button>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* LEVELS */}
                {screen === 'levels' && selectedDifficulty && (() => {
                    // Calculate global best time logic for both Header and Grid
                    const levelCount = getLevelCount(selectedDifficulty);
                    const allLevels = Array.from({ length: levelCount }, (_, i) => i + 1);

                    let globalBest = Infinity;
                    allLevels.forEach(l => {
                        const p = Storage.getLevelProgress(selectedDifficulty, l);
                        if (p?.bestTime !== undefined && p.bestTime < globalBest) {
                            globalBest = p.bestTime;
                        }
                    });
                    const hasGlobalBest = globalBest !== Infinity;

                    return (
                        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                            <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                            <button onClick={handleLevelBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                            <div className="w-full text-center mt-2 pointer-events-none">
                                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                                <p className="text-xs text-stone-400 uppercase tracking-widest mb-1">Select Level</p>
                                {hasGlobalBest && (
                                    <div className="flex flex-col items-center animate-fade-in mt-3">
                                        <span className="text-[8px] font-black text-amber-500 tracking-widest uppercase mb-px opacity-90">Best</span>
                                        <span className="text-lg font-medium text-stone-700 tabular-nums leading-none">{formatTimeShort(globalBest)}</span>
                                    </div>
                                )}
                            </div>
                            <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="absolute right-6 top-[20px] p-2 rounded-full hover:bg-stone-200 -mr-2"><Icons.Settings className="w-6 h-6 text-stone-600" /></button>
                            </div>

                            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                                <div className="w-full max-w-md grid grid-cols-5 gap-3">
                                    {allLevels.map((lvl) => {
                                            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
                                            const isCompleted = progress?.status === 'completed';
                                            const isInProgress = progress?.status === 'in-progress';
                                            const bestTime = progress?.bestTime;
                                            const isGlobalBest = hasGlobalBest && bestTime !== undefined && bestTime === globalBest;

                                            return (
                                                <button key={lvl} onClick={() => handleLevelSelect(lvl)} className={`aspect-square rounded-xl relative transition-all active:scale-90 ${isCompleted ? 'bg-stone-100 text-stone-300 border border-stone-100 ring-1 ring-inset ring-stone-900/5' : isInProgress ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}`}>
                                                    <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{lvl}</span></div>
                                                    {bestTime ? (
                                                        isGlobalBest ? (
                                                            <>
                                                                <div className="absolute top-1.5 inset-x-0 flex justify-center">
                                                                    <span className="text-[8px] font-black text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                                                                </div>
                                                                <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                                                                    <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                                                                </div>
                                                            </>
                                                        ) : (
                                                            <div className="absolute bottom-1.5 inset-x-0 text-center">
                                                                <span className="text-[10px] text-stone-400 font-bold tracking-tight block">{formatTimeShort(bestTime)}</span>
                                                            </div>
                                                        )
                                                    ) : null}
                                                </button>
                                            );
                                    })}
                                </div>
                                <div className="h-safe-bottom w-full shrink-0" />
                            </div>
                        </div>
                    );
                })()}

                {/* STORE */}
                {screen === 'store' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                         <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                              <button onClick={handleStoreBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                              <div className="w-full text-center mt-2 pointer-events-none"><h1 className="text-xl font-bold text-stone-800">Store</h1></div>
                              <div className="absolute right-6 top-[20px] flex items-center gap-1 bg-white px-3 py-2 rounded-full shadow-sm border border-stone-100">
                                  <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                  <span className="text-sm font-bold text-stone-700">{points}</span>
                              </div>
                         </div>
                         <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                              <div className="w-full max-w-md space-y-8">
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Backgrounds</h2>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 ml-1">Static</h3>
                                          <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : (bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : '')} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                                  <span className="text-sm font-bold text-stone-900 leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 ml-1">Dynamic</h3>
                                          <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                                  <span className="text-sm font-bold text-stone-900 leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                  </div>
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Numbers</h2>
                                      <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                                          const isPurchased = purchasedNumberColors.includes(num.id);
                                          const isSelected = selectedNumberColorId === num.id;
                                          return (
                                              <div key={num.id} className="flex flex-col items-center gap-1">
                                                  <button onClick={() => isPurchased ? handleSelectNumberColor(num.id) : initiatePurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-white ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                      <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                                          <span className={`text-3xl font-bold leading-none ${num.uiClass}`}>5</span>
                                                      </div>
                                                      {!isPurchased && (
                                                          <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                              <span className="text-sm font-bold text-stone-900 leading-none">{num.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{num.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>
                                  <div>
                                      <h2 className="text-lg font-bold text-stone-700 mb-4 ml-1">Skills</h2>
                                      <div className="grid grid-cols-5 gap-2">{SKILLS.map(skill => {
                                          const isPurchased = purchasedSkills.includes(skill.id);
                                          const isLocked = skill.locked;
                                          return (
                                              <div key={skill.id} className="flex flex-col items-center gap-1">
                                                  <button onClick={() => !isPurchased && !isLocked ? initiatePurchase(skill, 'skill') : null} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isPurchased ? 'bg-white ring-2 ring-inset ring-blue-500' : 'bg-white active:scale-95'} ${isLocked ? 'cursor-not-allowed opacity-60 bg-stone-100' : ''}`}>
                                                      <div className={`flex items-center justify-center w-full h-full ${!isPurchased && !isLocked ? 'pb-4' : ''}`}>
                                                          <skill.icon className={`w-8 h-8 ${skill.class}`} />
                                                      </div>
                                                      {!isPurchased && !isLocked && (
                                                          <div className="absolute bottom-0 inset-x-0 bg-white py-1 flex items-center justify-center gap-0.5">
                                                              <span className="text-sm font-bold text-stone-900 leading-none">{skill.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{skill.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* GAME */}
                {screen === 'game' && selectedDifficulty && selectedLevel && (
                    <div className="flex-1 w-full flex flex-col overflow-hidden" style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 16px)' }}>
                        <SudokuGame 
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {}} 
                            onSettingsOpen={() => { sounds.playClick(); setShowSettings(true); }}
                            onNextLevel={() => { sounds.playClick(); const max = getLevelCount(selectedDifficulty); if (selectedLevel < max) { setSelectedLevel(selectedLevel + 1); setPoints(Storage.getPoints()); } else transitionTo('levels'); }}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={purchasedSkills}
                        />
                    </div>
                )}

            </div>
          </div>

          {/* Global Modals - Z-Index 100+ */}
          {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
          {purchaseCandidate && <PurchaseModal item={purchaseCandidate} onConfirm={confirmPurchase} onCancel={() => { sounds.playClick(); setPurchaseCandidate(null); }} />}
          {replayLevelId && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in"><div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop"><h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3><p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p><div className="flex gap-3"><button onClick={() => { sounds.playClick(); setReplayLevelId(null); }} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button><button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button></div></div></div>}
          {showNotEnoughPoints && <NotEnoughPointsModal onClose={() => { sounds.playClick(); setShowNotEnoughPoints(false); }} onWatchAd={handleWatchAd} onGoPlay={handleGoPlay} />}
          {isWatchingAd && <AdOverlay />}

      </>
  );
}

export default App;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';
import { sounds } from '../utils/sound';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  onNextLevel: () => void;
  settings: any;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen?: boolean;
  backgroundClass?: string;
  numberColor?: string;
  purchasedSkills?: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onReturnToMenu,
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen = false,
  backgroundClass = 'bg-paper',
  numberColor = 'text-blue-600',
  purchasedSkills = [],
}) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);
  const [displayedPoints, setDisplayedPoints] = useState(0); 

  const [isResuming, setIsResuming] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isQuitting, setIsQuitting] = useState(false);
  const [showDeselectHint, setShowDeselectHint] = useState(false);

  const [animatingCell, setAnimatingCell] = useState<{r: number, c: number, value: number} | null>(null);

  const timerRef = useRef<any>(null);

  const initializeGame = useCallback(() => {
    setLoading(true);
    setShowRestartConfirm(false);
    setIsPaused(false);
    setIsCompleted(false);
    setIsEnding(false);
    setIsResuming(false);
    setIsRestarting(false);
    setIsQuitting(false);
    setHistory([]);
    setEarnedPoints(0);
    setDisplayedPoints(0);
    setShowDeselectHint(false);
    setAnimatingCell(null);

    const savedProgress = Storage.getLevelProgress(difficulty, levelId);

    if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
      setBoard(savedProgress.boardState);
      setTimer(savedProgress.timeElapsed);
      const { solved } = generateLevel(difficulty, levelId); 
      setSolvedBoard(solved);
    } else {
      const { initial, solved } = generateLevel(difficulty, levelId);
      setBoard(initial);
      setSolvedBoard(solved);
      setTimer(0);
    }
    setLoading(false);
  }, [difficulty, levelId]);

  useEffect(() => { initializeGame(); return () => stopTimer(); }, [initializeGame]);

  useEffect(() => {
    if (!loading) {
        const t1 = setTimeout(() => setShowDeselectHint(true), 100);
        const t2 = setTimeout(() => setShowDeselectHint(false), 7100);
        return () => { clearTimeout(t1); clearTimeout(t2); };
    }
  }, [loading]);

  const handleRestart = () => {
      sounds.playClick();
      setIsRestarting(true);
      setTimeout(() => { Storage.clearLevelProgress(difficulty, levelId); initializeGame(); }, 300);
  };

  const handleResume = () => { sounds.playClick(); setIsResuming(true); setTimeout(() => { setIsPaused(false); setIsResuming(false); }, 300); };
  const handleQuit = () => { sounds.playClick(); onBack(); };
  const handleNextLevelWithAnim = () => { sounds.playClick(); setIsQuitting(true); setTimeout(() => { onNextLevel(); }, 300); };

  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => setTimer((t) => t + 1), 1000);
  };
  const stopTimer = () => { if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; } };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted && !showRestartConfirm && !isEnding && !isSettingsOpen) startTimer();
    else stopTimer();
    return () => stopTimer();
  }, [loading, isPaused, isCompleted, showRestartConfirm, isEnding, isSettingsOpen]);

  useEffect(() => {
      if (isCompleted && earnedPoints > 0) {
          let startTime: number;
          const duration = 1500;
          const animate = (time: number) => {
              if (!startTime) startTime = time;
              const elapsed = time - startTime;
              const progress = Math.min(elapsed / duration, 1);
              const ease = 1 - Math.pow(1 - progress, 4);
              setDisplayedPoints(Math.floor(ease * earnedPoints));
              if (progress < 1) requestAnimationFrame(animate);
              else setDisplayedPoints(earnedPoints);
          };
          requestAnimationFrame(animate);
      }
  }, [isCompleted, earnedPoints]);

  const saveProgressInstant = (currentBoard: Board) => {
     if (loading || isCompleted) return;
     const progress: LevelProgress = {
        levelId, difficulty, status: 'in-progress',
        timeElapsed: timer, lastPlayed: Date.now(), boardState: currentBoard,
      };
      Storage.saveLevelProgress(progress);
  };

  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm || isEnding) return;
    const save = setInterval(() => saveProgressInstant(board), 5000);
    return () => clearInterval(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm, isEnding]);

  const conflicts = useMemo(() => {
      const conf = new Set<string>();
      if (loading || board.length === 0) return conf;
      const rows = Array.from({length: 9}, () => new Map<number, number[]>());
      const cols = Array.from({length: 9}, () => new Map<number, number[]>());
      const boxes = Array.from({length: 9}, () => new Map<number, number[]>());

      board.forEach((row, r) => {
          row.forEach((cell, c) => {
              if (cell.value !== null) {
                  const val = cell.value;
                  if (!rows[r].has(val)) rows[r].set(val, []);
                  rows[r].get(val)!.push(c);
                  if (!cols[c].has(val)) cols[c].set(val, []);
                  cols[c].get(val)!.push(r);
                  const b = Math.floor(r/3)*3 + Math.floor(c/3);
                  if (!boxes[b].has(val)) boxes[b].set(val, []);
                  boxes[b].get(val)!.push(r*9+c);
              }
          });
      });
      rows.forEach((rowMap, r) => rowMap.forEach((indices) => { if (indices.length > 1) indices.forEach(c => conf.add(`${r}-${c}`)); }));
      cols.forEach((colMap, c) => colMap.forEach((indices) => { if (indices.length > 1) indices.forEach(r => conf.add(`${r}-${c}`)); }));
      boxes.forEach((boxMap, b) => boxMap.forEach((indices) => { if (indices.length > 1) indices.forEach(flat => { const r = Math.floor(flat/9); const c = flat%9; conf.add(`${r}-${c}`); }); }));
      return conf;
  }, [board, loading]);

  const isAutoAvailable = useMemo(() => {
    if (!purchasedSkills.includes('skill-auto')) return false;
    if (!selectedCell) return false;
    const [r, c] = selectedCell;
    if (board[r][c].value !== null) return false;

    // Check Row
    let rowCount = 0;
    for(let i=0; i<9; i++) if (board[r][i].value !== null) rowCount++;
    if (rowCount === 8) return true;

    // Check Col
    let colCount = 0;
    for(let i=0; i<9; i++) if (board[i][c].value !== null) colCount++;
    if (colCount === 8) return true;

    // Check Box
    let boxCount = 0;
    const startR = Math.floor(r/3)*3;
    const startC = Math.floor(c/3)*3;
    for(let i=0; i<3; i++)
        for(let j=0; j<3; j++)
            if (board[startR+i][startC+j].value !== null) boxCount++;
    if (boxCount === 8) return true;

    return false;
  }, [board, selectedCell, purchasedSkills]);

  const handleCellClick = (e: React.MouseEvent, row: number, col: number) => {
    e.stopPropagation();
    if (isPaused || isCompleted || isEnding || isSettingsOpen) return;
    sounds.playTap();
    setSelectedCell([row, col]);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
    if (isPaused || isCompleted || isEnding || isSettingsOpen) return;
    if (selectedCell) setSelectedCell(null);
  };

  const getPointsForDifficulty = (diff: Difficulty) => {
      switch(diff) {
          case Difficulty.SuperEasy: return 5;
          case Difficulty.Easy: return 10;
          case Difficulty.Normal: return 15;
          case Difficulty.Hard: return 20;
          case Difficulty.Intense: return 30;
          case Difficulty.Impossible: return 50;
          default: return 0;
      }
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted || isEnding || isSettingsOpen) return;
    sounds.playNumber(num);
    const [r, c] = selectedCell;
    const currentCell = board[r][c];
    if (currentCell.isFixed) return;

    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
    const newBoard = board.map(row => [...row]);
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      if (newCell.notes.includes(num)) newCell.notes = newCell.notes.filter(n => n !== num);
      else newCell.notes = [...newCell.notes, num].sort();
    } else {
      if (newCell.value === num) { newCell.value = null; newCell.isError = false; }
      else {
        newCell.value = num as any;
        newCell.notes = [];
        // Only disable error checking for Hard and above
        const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        if (!isHarderDifficulty) newCell.isError = num !== solvedBoard[r][c];
        else newCell.isError = false; 
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);
    saveProgressInstant(newBoard);
    if (!isPencilMode && newCell.value) checkCompletion(newBoard);
  };

  const handleAutoFill = () => {
      if (!isAutoAvailable || !selectedCell || isPaused || isCompleted || isEnding) return;
      sounds.playZap(); // New sound
      const [r, c] = selectedCell;

      let valToFill: number | null = null;

      const getMissing = (values: (number | null)[]) => {
          const vals = new Set(values.filter(v => v !== null));
          for (let i = 1; i <= 9; i++) if (!vals.has(i)) return i;
          return null;
      };

      // Check Row
      if (board[r].filter(cell => cell.value !== null).length === 8) {
          valToFill = getMissing(board[r].map(c => c.value));
      }
      // Check Col
      if (valToFill === null) {
          const colVals = board.map(row => row[c].value);
          if (colVals.filter(v => v !== null).length === 8) {
              valToFill = getMissing(colVals);
          }
      }
      // Check Box
      if (valToFill === null) {
          const startR = Math.floor(r/3)*3;
          const startC = Math.floor(c/3)*3;
          const boxVals = [];
          for(let i=0; i<3; i++) for(let j=0; j<3; j++) boxVals.push(board[startR+i][startC+j].value);
          if (boxVals.filter(v => v !== null).length === 8) {
              valToFill = getMissing(boxVals);
          }
      }

      // Fallback
      if (valToFill === null) {
          valToFill = solvedBoard[r][c];
      }

      const val = valToFill as number;

      // Initialize animation state immediately to prevent flash of final number
      setAnimatingCell({ r, c, value: 1 });

      setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
      const newBoard = board.map(row => [...row]);

      // Update check here as well to match handleNumberInput
      const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
      const isCorrect = val === solvedBoard[r][c];

      newBoard[r][c] = {
          ...newBoard[r][c],
          value: val as any,
          notes: [],
          isError: !isHarderDifficulty ? !isCorrect : false
      };

      setBoard(newBoard);
      saveProgressInstant(newBoard);

      const startTime = performance.now();
      const duration = 300; // Faster animation (0.3s)

      const animate = (time: number) => {
          const elapsed = time - startTime;
          const progress = Math.min(elapsed / duration, 1);

          // Count from 1 to val (if val is 1, it stays 1; if 9, it counts up)
          const currentVal = Math.floor(1 + (val - 1) * progress);
          setAnimatingCell({ r, c, value: currentVal });

          if (progress < 1) {
              requestAnimationFrame(animate);
          } else {
              setAnimatingCell(null);
          }
      };
      requestAnimationFrame(animate);

      checkCompletion(newBoard);
  };

  const checkCompletion = (currentBoard: Board) => {
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }
      if (filled === 81 && correct === 81) {
          setIsEnding(true);
          stopTimer();
          setTimeout(() => {
              sounds.playWin();
              setIsCompleted(true);
              const points = getPointsForDifficulty(difficulty);
              setEarnedPoints(points);
              onEarnPoints(points);
              const progress: LevelProgress = { levelId, difficulty, status: 'completed', timeElapsed: timer, lastPlayed: Date.now(), boardState: undefined };
              Storage.saveLevelProgress(progress);
          }, 1000);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused || isEnding || isSettingsOpen) return;
    sounds.playClick();
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;
    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = board.map(row => [...row]);
    newBoard[r][c].value = null; newBoard[r][c].notes = []; newBoard[r][c].isError = false;
    setBoard(newBoard);
    saveProgressInstant(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused || isEnding || isSettingsOpen) return;
    sounds.playClick();
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
    saveProgressInstant(previous);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getCellClass = (cell: Cell, r: number, c: number) => {
    let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
    const isConflict = conflicts.has(`${r}-${c}`);
    const isError = cell.isError;
    const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;
    const isSameValue = selectedCell && cell.value !== null && board[selectedCell[0]][selectedCell[1]].value === cell.value;
    const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

    // Background Logic
    let bgClass = 'bg-white ';
    if (isError || isConflict) {
        bgClass = 'bg-red-50 ';
    } else if (isSelected) {
        bgClass = 'bg-blue-200 '; // Selected cell
    } else if (settings.highlight && isSameValue) {
        bgClass = 'bg-[#c6defe] '; // Custom Blue-175
    } else if (settings.highlight && isRelated) {
        bgClass = 'bg-stone-100 '; // Row/Col/Box
    }

    classes += bgClass;

    // Selection Ring Logic
    if (isSelected && (isError || isConflict)) {
        classes += "ring-2 ring-inset ring-red-400 z-10 ";
    }

    // Text Color Logic
    if (cell.isFixed) {
        classes += "font-semibold text-stone-800 ";
    } else {
        if (isError || isConflict) {
            classes += "font-medium text-red-500 ";
        } else {
            classes += "font-medium ";
        }
    }
    return classes;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  // Reduced height slightly to accommodate the top shift and prevent overflow on small screens
  const squareSize = 'min(90vw, 50dvh)';
  const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
  const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
  const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

  return (
    <div className={`flex-1 flex flex-col w-full max-w-lg mx-auto relative ${isQuitting ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={handleBackgroundClick}>

      {/* Header */}
      <div className="flex-none pb-2 px-6 w-full relative z-20 min-h-[60px] pt-[20px]">
        <button onClick={(e) => { e.stopPropagation(); handleQuit(); }} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6 text-stone-600" /></button>
        {/* Adjusted top position to 60px as requested */}
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center pointer-events-none top-[60px]">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>
        <div className="absolute right-6 flex flex-col items-end gap-1 -mr-2 top-[20px]">
            <div className="flex gap-1">
                <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200 transition"><Icons.Pause className="w-6 h-6 text-stone-600" /></button>
                <button onClick={(e) => { e.stopPropagation(); onSettingsOpen(); }} className="p-2 rounded-full hover:bg-stone-200 transition"><Icons.Settings className="w-6 h-6 text-stone-600" /></button>
            </div>
            <div className="flex items-center gap-1 bg-stone-100 px-2 py-1 rounded-full mr-1">
                <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                <span className="text-xs font-bold text-stone-600 tabular-nums">{currentPoints}</span>
            </div>
        </div>
      </div>

      {/* Main Board Container - Added pt-[60px] to push content down */}
      <div className="flex-1 w-full flex flex-col items-center justify-center min-h-0 px-4 pb-8 pt-[60px]">
         <div className="bg-white border-2 border-stone-800 rounded-lg overflow-hidden relative flex-none" style={{ width: squareSize, height: squareSize, maxWidth: '500px', maxHeight: '500px' }}>
            {/* SVG Grid Overlay */}
            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;
                    const isConflict = conflicts.has(`${rIndex}-${cIndex}`);
                    return (
                        <div key={`${rIndex}-${cIndex}`} className={getCellClass(cell, rIndex, cIndex)} onClick={(e) => handleCellClick(e, rIndex, cIndex)} style={{ fontSize: mainFontSize }}>
                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] ${!cell.isFixed && !cell.isError && !isConflict ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none">
                                {[1,2,3,4,5,6,7,8,9].map(n => (
                                    <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                        <span className={cell.notes.includes(n) ? 'text-stone-500' : 'invisible'}>{n}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>
         </div>

         {/* Spacer */}
         <div className="flex-none h-[20px] sm:h-[40px]"></div>

         {/* Controls */}
         <div className="flex-none w-full max-w-lg flex flex-col gap-3">
             <div className="flex justify-between px-2">
                <button onClick={(e) => { e.stopPropagation(); handleUndo(); }} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition"><div className="p-3 bg-white rounded-full border border-stone-100 shadow-sm"><Icons.Undo className="w-5 h-5" /></div><span className="text-xs">Undo</span></button>
