                {/* Scan Skill Button */}
                {purchasedSkills.includes('skill-scan') && (
                     <button 
                        onClick={(e) => { e.stopPropagation(); handleScan(); }} 
                        className={`flex flex-col items-center gap-1 transition active:scale-95 relative ${scanUses > 0 && !scanCooldown && !isScanning ? 'cursor-pointer text-stone-500' : 'cursor-not-allowed text-stone-300'}`}
