export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onReturnToMenu,
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen = false,
  backgroundClass = 'bg-paper',
  numberColor = 'text-blue-600',
  purchasedSkills = [],
}) => {
