                     <div className="flex gap-3"><button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button><button onClick={(e) => { e.stopPropagation(); handleRestart(); }} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button></div>
                  </div>
