      {isCompleted && (
          <div className="fixed inset-0 bg-green-500/50 backdrop-blur-sm z-[100] flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-500"><Icons.Check className="w-10 h-10 animate-scale-loop" /></div>
                  <div className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-1">{difficulty} &bull; Level {levelId}</div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-2 text-sm">You earned</p>
                  <div className="flex items-center justify-center gap-2 mb-4"><div className="text-blue-500"><Icons.Diamond className="w-6 h-6 fill-current" /></div><span className="text-3xl font-bold text-stone-800">+{displayedPoints}</span></div>
                  <p className="text-stone-400 mb-2 text-xs uppercase tracking-wide">Time</p>
                  <p className="text-2xl font-medium mb-8 tabular-nums">{formatTime(timer)}</p>
                  <div className="flex flex-col gap-3">
                    <button onClick={(e) => { e.stopPropagation(); handleNextLevelWithAnim(); }} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg active:opacity-80">Play Next Level</button>
