const SKILLS = [
    { id: 'skill-auto', name: 'Auto', cost: 750, icon: Icons.Auto, class: 'text-amber-500', description: "Automatically fills a cell when it's the only option left in a row, column, or box." },
    { id: 'skill-scan', name: 'Scan', cost: 750, icon: Icons.Scan, class: 'text-red-500', description: "Checks the board for errors and highlights incorrect cells." },
    { id: 'skill-reveal', name: 'Reveal', cost: 1000, icon: Icons.Reveal, class: 'text-purple-500', description: "Reveals the correct number for a random empty cell." },
];

const ALL_BACKGROUNDS = [...STATIC_BACKGROUNDS, ...DYNAMIC_BACKGROUNDS];

