      if (offer.id === 'starter_pack') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          handleEarnPoints(1000);

          // Grant items (using 0 cost to bypass point check, or assuming user has points)
          // Since this is a real-money purchase, points are irrelevant for the unlocks.
          // We assume Storage.purchase... handles 'already owned' gracefully or we check.

          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseNumberColor('num-purple', 0);
          Storage.purchaseNumberColor('num-teal', 0);
      }
      */
  };

