export default App;

class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        // Always try to resume if suspended (browsers block autoplay)
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    private vibrate(pattern: number | number[]) {
        if (!this.vibrationEnabled) return;
        if (typeof navigator !== 'undefined' && navigator.vibrate) {
            try {
                navigator.vibrate(pattern);
            } catch (e) {
                // Ignore vibration errors or lack of support
            }
        }
    }

    private playTone(freq: number, type: 'sine' | 'triangle', duration: number, volume: number) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = type;
            osc.frequency.setValueAtTime(freq, ctx.currentTime);

            const t = ctx.currentTime;
            const attack = 0.01;

            // Envelope
            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(volume, t + attack);
            // Exponential ramp to near zero (avoiding actual 0 which throws error)
            gain.gain.exponentialRampToValueAtTime(0.001, t + duration);

            osc.start(t);
            osc.stop(t + duration + 0.05); // Stop slightly after envelope finishes
        } catch (e) {
            // Ignore audio errors
        }
    }

    // Standard UI button click
    playClick() {
        this.vibrate(10); 
        this.playTone(800, 'sine', 0.1, 0.3); // Louder and slightly longer
    }

    // Grid selection tap
    playTap() {
        this.vibrate(4);
        this.playTone(600, 'triangle', 0.08, 0.2); // Louder and slightly longer
    }

    // Number input (C Major Pentatonic)
    playNumber(num: number) {
        this.vibrate(8);
        const freqs = [
            523.25, // C5
            587.33, // D5
            659.25, // E5
            783.99, // G5
            880.00, // A5
            1046.50, // C6
            1174.66, // D6
            1318.51, // E6
            1567.98  // G6
        ];
        const freq = freqs[num - 1] || 440;
        this.playTone(freq, 'sine', 0.15, 0.35); // Louder
    }

    // Action confirmation (Purchase, etc.)
    playPop() {
        this.vibrate(15);
        this.playTone(400, 'sine', 0.15, 0.4); // Louder
    }

    // Auto Skill
    playZap() {
        this.vibrate(12);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            const t = ctx.currentTime;

            osc.frequency.setValueAtTime(1200, t);
            osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.3, t + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);

            osc.start(t);
            osc.stop(t + 0.2);
        } catch (e) {}
    }

    // Scan Skill
    playScan() {
        this.vibrate(20);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'triangle';
            const t = ctx.currentTime;

            osc.frequency.setValueAtTime(200, t);
            osc.frequency.linearRampToValueAtTime(800, t + 0.8);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.15, t + 0.1);
            gain.gain.linearRampToValueAtTime(0.15, t + 0.6);
            gain.gain.linearRampToValueAtTime(0, t + 0.8);

            osc.start(t);
            osc.stop(t + 0.8);
        } catch (e) {}
    }

    // Reveal Skill
    playReveal() {
        this.vibrate(25); 
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            // E Major 9 chord
            const freqs = [329.63, 415.30, 493.88, 622.25, 739.99]; 

            freqs.forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();

                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq, t);

                const start = t + (i * 0.04);
                gain.gain.setValueAtTime(0, start);
                gain.gain.linearRampToValueAtTime(0.15, start + 0.05); 
                gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0);

                osc.start(start);
                osc.stop(start + 2.0);
            });
        } catch (e) {}
    }

    playWin() {
        this.vibrate([50, 50, 50, 50, 100]);
        if (!this.soundEnabled) return;
        const notes = [523.25, 659.25, 783.99, 1046.50]; // C Major
        notes.forEach((freq, i) => {
            setTimeout(() => {
                this.playTone(freq, 'sine', 0.4, 0.4); 
            }, i * 100);
        });
    }
}

export const sounds = new SoundController();

import { AppSettings, LevelProgress, StoredData } from '../types';

const STORAGE_KEY = 'minimal_sudoku_data_v1';

const DEFAULT_SETTINGS: AppSettings = {
  music: false,
  sound: true,
  highlight: true,
  autoNotes: false,
  vibration: true,
};

function getStoredData(): StoredData {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return { 
          settings: DEFAULT_SETTINGS, 
          points: 0,
          progress: {},
          purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
          selectedBackground: 'bg-default',
          purchasedNumberColors: ['num-default'],
          selectedNumberColor: 'num-default',
          purchasedSkills: [],
          bonusClaimed: false,
          starterPackPurchased: false,
      };
    }
    const data = JSON.parse(raw);

    // Migrations
    if (typeof data.points !== 'number') data.points = 0;

    if (!data.purchasedBackgrounds) data.purchasedBackgrounds = ['bg-default', 'bg-dyn-default'];
    // Ensure defaults are always owned
    if (!data.purchasedBackgrounds.includes('bg-default')) data.purchasedBackgrounds.push('bg-default');
    if (!data.purchasedBackgrounds.includes('bg-dyn-default')) data.purchasedBackgrounds.push('bg-dyn-default');

    if (data.selectedBackground === undefined) data.selectedBackground = 'bg-default';

    if (!data.purchasedNumberColors) data.purchasedNumberColors = ['num-default'];
    if (!data.selectedNumberColor) data.selectedNumberColor = 'num-default';

    if (data.settings.vibration === undefined) data.settings.vibration = true;

    if (!data.purchasedSkills) data.purchasedSkills = [];

    if (data.bonusClaimed === undefined) data.bonusClaimed = false;

    if (data.starterPackPurchased === undefined) data.starterPackPurchased = false;

    return data;
  } catch (e) {
    console.error("Failed to load data", e);
    return { 
        settings: DEFAULT_SETTINGS, 
        points: 0, 
        progress: {},
        purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
        selectedBackground: 'bg-default',
        purchasedNumberColors: ['num-default'],
        selectedNumberColor: 'num-default',
        purchasedSkills: [],
        bonusClaimed: false,
        starterPackPurchased: false,
    };
  }
}

function saveData(data: StoredData) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (e) {
    console.error("Failed to save data", e);
  }
}

export const Storage = {
  getSettings: (): AppSettings => {
    return getStoredData().settings;
  },

  saveSettings: (settings: AppSettings) => {
    const data = getStoredData();
    data.settings = settings;
    saveData(data);
  },

  getPoints: (): number => {
    return getStoredData().points;
  },

  addPoints: (amount: number) => {
    const data = getStoredData();
    data.points += amount;
    saveData(data);
    return data.points;
  },

  // Store Methods - Backgrounds
  getPurchasedBackgrounds: (): string[] => {
      return getStoredData().purchasedBackgrounds;
  },

  getSelectedBackground: (): string | null => {
      return getStoredData().selectedBackground;
  },

  purchaseBackground: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedBackgrounds.includes(id)) {
          data.points -= cost;
          data.purchasedBackgrounds.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectBackground: (id: string | null) => {
      const data = getStoredData();
      data.selectedBackground = id;
      saveData(data);
  },

  // Store Methods - Number Colors
  getPurchasedNumberColors: (): string[] => {
      return getStoredData().purchasedNumberColors;
  },

  getSelectedNumberColor: (): string => {
      return getStoredData().selectedNumberColor;
  },

  purchaseNumberColor: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedNumberColors.includes(id)) {
          data.points -= cost;
          data.purchasedNumberColors.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectNumberColor: (id: string) => {
      const data = getStoredData();
      data.selectedNumberColor = id;
      saveData(data);
  },

  // Store Methods - Skills
  getPurchasedSkills: (): string[] => {
      return getStoredData().purchasedSkills;
  },

  purchaseSkill: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedSkills.includes(id)) {
          data.points -= cost;
          data.purchasedSkills.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  isBonusClaimed: (): boolean => {
      return !!getStoredData().bonusClaimed;
  },

  setBonusClaimed: () => {
      const data = getStoredData();
      data.bonusClaimed = true;
      saveData(data);
  },

  isStarterPackPurchased: (): boolean => {
      return !!getStoredData().starterPackPurchased;
  },

  setStarterPackPurchased: () => {
      const data = getStoredData();
      data.starterPackPurchased = true;
      saveData(data);
  },

  getLevelProgress: (difficulty: string, levelId: number): LevelProgress | undefined => {
    const key = `${difficulty}-${levelId}`;
    return getStoredData().progress[key];
  },

  saveLevelProgress: (progress: LevelProgress) => {
    const data = getStoredData();
    const key = `${progress.difficulty}-${progress.levelId}`;
    const existing = data.progress[key];

    // Handle Best Time Logic
    let bestTime = existing?.bestTime;

    if (progress.status === 'completed') {
        if (bestTime === undefined || progress.timeElapsed < bestTime) {
            bestTime = progress.timeElapsed;
        }
    }

    data.progress[key] = {
        ...progress,
        bestTime: bestTime
    };

    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
           const { bestTime } = data.progress[key];

           data.progress[key] = {
               levelId,
               difficulty: difficulty as any,
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               history: [],
               bestTime: bestTime,
               scanUses: 3,
               revealUses: 1 
           };
           saveData(data);
      }
  },

  resetAllData: () => {
    localStorage.removeItem(STORAGE_KEY);
  },

  getCompletedCount: (difficulty: string): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => p.difficulty === difficulty && p.status === 'completed').length;
  }
};

