                    <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                    <button onClick={handleClose} className="p-2 bg-stone-200 rounded-full hover:bg-stone-300 text-stone-700 transition-colors"><Icons.Close className="w-5 h-5" /></button>
                </div>
                <div className="space-y-2">
                    {['sound', 'vibration', 'highlight'].map((key) => (
                         <div key={key} className="flex items-center justify-between px-3 py-2 rounded-xl bg-stone-50">
