                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-stone-500 font-medium truncate w-full text-center">{num.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* GAME */}
                {screen === 'game' && selectedDifficulty && selectedLevel && (
                    <div className="flex-1 w-full flex flex-col overflow-hidden" style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 16px)' }}>
                        <SudokuGame 
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {}} 
                            onSettingsOpen={() => { sounds.playClick(); setShowSettings(true); }}
                            onNextLevel={() => { sounds.playClick(); const max = getLevelCount(selectedDifficulty); if (selectedLevel < max) { setSelectedLevel(selectedLevel + 1); setPoints(Storage.getPoints()); } else transitionTo('levels'); }}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={purchasedSkills}
                        />
                    </div>
                )}

            </div>
          </div>

          {/* Global Modals - Z-Index 100+ */}
          {activeTooltip && <SkillTooltip {...activeTooltip} />}
          {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
          {purchaseCandidate && <PurchaseModal item={purchaseCandidate} onConfirm={confirmPurchase} onCancel={() => { setPurchaseCandidate(null); }} />}
          {replayLevelId && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in"><div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop"><h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3><p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p><div className="flex gap-3"><button onClick={() => { sounds.playClick(); setReplayLevelId(null); }} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button><button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button></div></div></div>}
          {showNotEnoughPoints && <NotEnoughPointsModal onClose={() => { setShowNotEnoughPoints(false); }} onWatchAd={handleWatchAd} onGoPlay={handleGoPlay} />}
          {isWatchingAd && <AdOverlay />}

      </>
  );
}

