                    </div>
                )}

                {/* DIAMOND SHOP */}
                {screen === 'diamondShop' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden bg-white">
                        <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                            <button onClick={handleDiamondShopBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                            <div className="w-full text-center mt-2 pointer-events-none">
                                {/* Header Title Removed */}
