class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        // Always try to resume if suspended (browsers block autoplay)
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    private vibrate(pattern: number | number[]) {
        if (!this.vibrationEnabled) return;
        if (typeof navigator !== 'undefined' && navigator.vibrate) {
            try {
                navigator.vibrate(pattern);
            } catch (e) {
                // Ignore vibration errors or lack of support
            }
        }
    }

    private playTone(freq: number, type: 'sine' | 'triangle', duration: number, volume: number) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = type;
            osc.frequency.setValueAtTime(freq, ctx.currentTime);

            const t = ctx.currentTime;
            const attack = 0.01;

            // Envelope
            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(volume, t + attack);
            // Exponential ramp to near zero (avoiding actual 0 which throws error)
            gain.gain.exponentialRampToValueAtTime(0.001, t + duration);

            osc.start(t);
            osc.stop(t + duration + 0.05); // Stop slightly after envelope finishes
        } catch (e) {
            // Ignore audio errors
        }
    }

    // Standard UI button click
    playClick() {
        this.vibrate(10); 
        this.playTone(800, 'sine', 0.1, 0.3); // Louder and slightly longer
    }

    // Grid selection tap
    playTap() {
        this.vibrate(4);
        this.playTone(600, 'triangle', 0.08, 0.2); // Louder and slightly longer
    }

    // Number input (C Major Pentatonic)
    playNumber(num: number) {
        this.vibrate(8);
        const freqs = [
            523.25, // C5
            587.33, // D5
            659.25, // E5
            783.99, // G5
            880.00, // A5
            1046.50, // C6
            1174.66, // D6
            1318.51, // E6
            1567.98  // G6
        ];
        const freq = freqs[num - 1] || 440;
        this.playTone(freq, 'sine', 0.15, 0.35); // Louder
    }

    // Action confirmation (Purchase, etc.)
    playPop() {
        this.vibrate(15);
        this.playTone(400, 'sine', 0.15, 0.4); // Louder
    }

    // Level Enter Sound (Gentle slide up)
    playLevelEnter() {
        this.vibrate(20);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            const t = ctx.currentTime;

            // Slide from G4 to C5
            osc.frequency.setValueAtTime(392.00, t); 
            osc.frequency.exponentialRampToValueAtTime(523.25, t + 0.2);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.3, t + 0.05);
            gain.gain.linearRampToValueAtTime(0.2, t + 0.15);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);

            osc.start(t);
            osc.stop(t + 0.3);
        } catch (e) {}
    }

    // Auto Skill
    playZap() {
        this.vibrate(12);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            const t = ctx.currentTime;

            osc.frequency.setValueAtTime(1200, t);
            osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.3, t + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);

            osc.start(t);
            osc.stop(t + 0.2);
        } catch (e) {}
    }

    // Scan Skill
    playScan() {
        this.vibrate(20);
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'triangle';
            const t = ctx.currentTime;

            osc.frequency.setValueAtTime(200, t);
            osc.frequency.linearRampToValueAtTime(800, t + 0.8);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.15, t + 0.1);
            gain.gain.linearRampToValueAtTime(0.15, t + 0.6);
            gain.gain.linearRampToValueAtTime(0, t + 0.8);

            osc.start(t);
            osc.stop(t + 0.8);
        } catch (e) {}
    }

    // Reveal Skill
    playReveal() {
        this.vibrate(25); 
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            // E Major 9 chord
            const freqs = [329.63, 415.30, 493.88, 622.25, 739.99]; 

            freqs.forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();

                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq, t);

                const start = t + (i * 0.04);
                gain.gain.setValueAtTime(0, start);
                gain.gain.linearRampToValueAtTime(0.15, start + 0.05); 
                gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0);

                osc.start(start);
                osc.stop(start + 2.0);
            });
        } catch (e) {}
    }

    playWin() {
        this.vibrate([50, 50, 50, 50, 100]);
        if (!this.soundEnabled) return;
        const notes = [523.25, 659.25, 783.99, 1046.50]; // C Major
        notes.forEach((freq, i) => {
            setTimeout(() => {
                this.playTone(freq, 'sine', 0.4, 0.4); 
            }, i * 100);
        });
    }
}

