            </div>
         </div>
      </div>

      {/* Overlays */}

      {(isPaused || showRestartConfirm) && (
          <div className={`fixed inset-0 bg-stone-50/90 backdrop-blur-sm z-[100] flex items-center justify-center ${(isResuming || isRestarting) ? 'animate-fade-out' : 'animate-fade-in'}`}>
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 mb-4 text-center">Game Paused</h2>
                    <button onClick={(e) => { e.stopPropagation(); handleResume(); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90"><Icons.Play className="w-5 h-5" /> Resume</button>
                    <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition hover:bg-stone-50"><Icons.Reset className="w-5 h-5" /> Restart Level</button>
