                    <button onClick={(e) => { e.stopPropagation(); handleNextLevelWithAnim(); }} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg active:opacity-80">Play Next Level</button>
