                             >
                                 {opt === 'system' && <Icons.System className="w-4 h-4" />}
                                 {opt === 'light' && <Icons.Sun className="w-4 h-4" />}
                                 {opt === 'dark' && <Icons.Moon className="w-4 h-4" />}
                                 <span className="capitalize">{opt}</span>
                             </button>
                         ))}
                     </div>
                </div>

                <div className="space-y-2">
                    {['sound', 'vibration', 'highlight', 'showTimer'].map((key) => (
                         <div key={key} className="flex items-center justify-between px-3 py-2 rounded-xl bg-t-surface-sec">
                            <div className="flex items-center gap-3 text-t-primary capitalize">
                                {key === 'sound' && <Icons.Sound className="w-5 h-5" />}
                                {key === 'vibration' && <Icons.Vibration className="w-5 h-5" />}
                                {key === 'highlight' && <Icons.Eye className="w-5 h-5" />}
                                {key === 'showTimer' && <Icons.Clock className="w-5 h-5" />}
                                <span>{
                                    key === 'highlight' ? 'Highlight Areas' : 
                                    key === 'showTimer' ? 'Show Timer' :
                                    key
                                }</span>
                            </div>
                            <button onClick={() => onToggle(key as keyof AppSettings)} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings[key as keyof AppSettings] ? 'bg-green-500' : 'bg-stone-300'}`}>
                                <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings[key as keyof AppSettings] ? 'translate-x-5' : 'translate-x-0'}`}></div>
                            </button>
                        </div>
                    ))}
                </div>
                <div className="mt-8 pt-6 border-t border-t-border">
                    <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                        <Icons.Trash className="w-5 h-5" /> Reset All Progress
                    </button>
                </div>
            </div>
        </div>
