                                          <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'var(--overlay-opacity)' }} />
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                                  <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-t-secondary font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                  </div>

                                  {/* NUMBER COLORS */}
                                  <div>
                                      <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                                      <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                                          const isPurchased = purchasedNumberColors.includes(num.id);
                                          const isSelected = selectedNumberColorId === num.id;
                                          return (
                                              <div key={num.id} className="flex flex-col items-center gap-1">
                                                  <button onClick={() => isPurchased ? handleSelectNumberColor(num.id) : initiatePurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                                      <span className={`text-2xl font-bold ${num.uiClass}`}>5</span>
                                                      {!isPurchased && (
                                                          <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                              <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-t-secondary font-medium truncate w-full text-center">{num.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>

                                  {/* INFO */}
                                  <div className="text-center pt-4 pb-8">
                                      <p className="text-xs text-t-secondary max-w-xs mx-auto">
                                          Unlock backgrounds and styles using diamonds earned by playing.
                                      </p>
                                  </div>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* GAME */}
                {screen === 'game' && selectedDifficulty && selectedLevel && (
                    <SudokuGame
                        difficulty={selectedDifficulty}
                        levelId={selectedLevel}
                        onBack={handleGameBack}
                        onReturnToMenu={handleReturnToMenu}
                        onComplete={() => {
                            setPoints(Storage.getPoints());
                        }}
                        onNextLevel={() => {
                            const nextLevel = selectedLevel + 1;
                            // Check if next level is within bounds (1-100)
                            if (nextLevel <= 100) {
                                handleLevelSelect(nextLevel);
                            } else {
                                handleReturnToMenu();
                            }
                        }}
                        onSettingsOpen={() => setShowSettings(true)}
                        settings={settings}
                        onEarnPoints={handleEarnPoints}
                        currentPoints={points}
                        isSettingsOpen={showSettings}
                        backgroundClass={activeBackgroundClass}
                        numberColor={numberColorClass}
                        purchasedSkills={purchasedSkills}
                    />
                )}
            </div>

            {/* GLOBAL OVERLAYS */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                />
            )}

            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}

            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onWatchAd={handleWatchAd} 
                    onGoPlay={handleGoPlay} 
                />
            )}

            {isWatchingAd && <AdOverlay />}

            {activeTooltip && (
                <SkillTooltip 
                    {...activeTooltip}
                />
            )}

          </div>
      </>
  );
}

import React, { useState, useEffect } from 'react';
