                {screen === 'store' && (
                    <div className="flex-1 w-full flex flex-col items-center overflow-hidden" onClick={() => setActiveTooltip(null)}>
                        {/* Header */}
                        <div className="w-full max-w-md flex items-start px-6 pb-4 relative shrink-0 pt-[60px]">
                            <button onClick={handleStoreBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6 text-t-icon" /></button>
                            <div className="w-full text-center mt-2 pointer-events-none">
                                <span className="text-xl font-bold text-t-primary">Store</span>
