                                {/* SKILLS */}
                                <div>
                                    <h3 className="text-sm font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Skills</h3>
                                    <div className="flex flex-col gap-3">
                                        {SKILLS.map(skill => {
                                            const owned = purchasedSkills.includes(skill.id);
                                            return (
                                                <div key={skill.id} className="bg-t-surface border border-t-border p-4 rounded-2xl flex items-center justify-between shadow-sm">
                                                    <div className="flex items-center gap-4">
                                                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${owned ? 'bg-stone-100 dark:bg-stone-800' : 'bg-stone-50 dark:bg-stone-900'}`}>
                                                            <skill.icon className={`w-6 h-6 ${owned ? skill.class : 'text-stone-300'}`} />
                                                        </div>
                                                        <div>
                                                            <div className="flex items-center gap-2">
                                                                <h4 className="font-bold text-t-primary">{skill.name}</h4>
                                                                <button onClick={(e) => handleSkillClick(e, skill)} className="text-t-secondary hover:text-blue-500 transition"><Icons.Hint className="w-4 h-4" /></button>
                                                            </div>
                                                            <p className="text-xs text-t-secondary">{owned ? 'Unlocked' : 'Permanent Upgrade'}</p>
                                                        </div>
                                                    </div>
                                                    {owned ? (
                                                        <div className="text-green-500 font-bold text-sm flex items-center gap-1"><Icons.Check className="w-5 h-5" /> Owned</div>
                                                    ) : (
                                                        <button onClick={() => initiatePurchase(skill, 'skill')} className="px-4 py-2 bg-stone-800 text-white dark:bg-stone-200 dark:text-stone-900 rounded-xl font-bold text-sm shadow-md active:scale-95 transition flex items-center gap-1">
                                                            {skill.cost} <Icons.Diamond className="w-3 h-3 fill-current" />
                                                        </button>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>

                                {/* BACKGROUNDS */}
                                <div>
                                    <h3 className="text-sm font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Themes</h3>

                                    {/* Static */}
                                    <div className="mb-4">
                                        <h4 className="text-xs font-bold text-t-secondary mb-2 ml-1">Static</h4>
                                        <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                            {STATIC_BACKGROUNDS.map(bg => {
                                                const owned = purchasedBackgrounds.includes(bg.id);
                                                const selected = selectedBackgroundId === bg.id;
                                                return (
                                                    <div key={bg.id} className="flex flex-col gap-2">
                                                        <button 
                                                            onClick={() => owned ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')}
