                                            })}
                                        </div>
                                    </div>

                                    {/* Dynamic */}
                                    <div>
                                        <h4 className="text-xs font-bold text-t-secondary mb-2 ml-1">Atmosphere <span className="text-[9px] bg-blue-100 text-blue-600 px-1.5 py-0.5 rounded ml-1">ANIMATED</span></h4>
                                        <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                            {DYNAMIC_BACKGROUNDS.map(bg => {
                                                const owned = purchasedBackgrounds.includes(bg.id);
                                                const selected = selectedBackgroundId === bg.id;
                                                return (
                                                    <div key={bg.id} className="flex flex-col gap-2">
                                                        <button 
                                                            onClick={() => owned ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')}
                                                            className={`aspect-square rounded-2xl border-2 relative overflow-hidden transition active:scale-95 ${selected ? 'border-blue-500 ring-2 ring-blue-200' : 'border-transparent'} ${bg.class}`}
                                                        >
                                                            {!owned && (
                                                                <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                                                                    <Icons.Diamond className="w-6 h-6 text-white opacity-80" />
                                                                </div>
                                                            )}
                                                            {selected && (
                                                                <div className="absolute top-2 right-2 w-5 h-5 bg-blue-500 rounded-full flex items-center justify-center border-2 border-white"><Icons.Check className="w-3 h-3 text-white" /></div>
                                                            )}
                                                        </button>
                                                        <div className="flex justify-between items-center px-1">
                                                            <span className="text-xs font-medium text-t-primary truncate">{bg.name}</span>
                                                            {!owned && <span className="text-xs font-bold text-stone-500 flex items-center gap-0.5">{bg.cost}<Icons.Diamond className="w-2 h-2 fill-current" /></span>}
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                </div>

                                {/* NUMBER COLORS */}
                                <div>
                                    <h3 className="text-sm font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Number Styles</h3>
                                    <div className="grid grid-cols-3 sm:grid-cols-5 gap-3">
                                        {NUMBER_COLORS.map(num => {
                                            const owned = purchasedNumberColors.includes(num.id);
                                            const selected = selectedNumberColorId === num.id;
                                            return (
                                                <div key={num.id} className="flex flex-col gap-2 items-center">
                                                    <button 
                                                        onClick={() => owned ? handleSelectNumberColor(num.id) : initiatePurchase(num, 'num')}
                                                        className={`w-full aspect-square rounded-2xl border-2 flex items-center justify-center text-3xl font-bold bg-t-surface shadow-sm transition active:scale-95 ${selected ? 'border-blue-500 ring-2 ring-blue-200' : 'border-t-border'} ${num.uiClass}`}
                                                    >
                                                        5
                                                    </button>
                                                    <div className="text-center w-full">
                                                        <div className="text-xs font-medium text-t-primary truncate">{num.name}</div>
                                                        {!owned && <div className="text-xs font-bold text-stone-500 flex items-center justify-center gap-0.5">{num.cost}<Icons.Diamond className="w-2 h-2 fill-current" /></div>}
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                                <div className="h-safe-bottom w-full shrink-0" />
                            </div>
                        </div>
                    </div>
                )}

                {/* GAME */}
                {screen === 'game' && selectedDifficulty && selectedLevel && (
                    <SudokuGame
                        difficulty={selectedDifficulty}
                        levelId={selectedLevel}
                        onBack={handleGameBack}
                        onReturnToMenu={handleReturnToMenu}
                        onComplete={() => {
                            setPoints(Storage.getPoints());
                        }}
                        onNextLevel={() => {
                            const nextLevel = selectedLevel + 1;
                            // Check if next level is within bounds (1-100)
                            if (nextLevel <= 100) {
                                handleLevelSelect(nextLevel);
                            } else {
                                handleReturnToMenu();
                            }
                        }}
                        onSettingsOpen={() => setShowSettings(true)}
                        settings={settings}
                        onEarnPoints={handleEarnPoints}
                        currentPoints={points}
                        isSettingsOpen={showSettings}
                        backgroundClass={activeBackgroundClass}
                        numberColor={numberColorClass}
                        purchasedSkills={purchasedSkills}
                    />
                )}
            </div>

            {/* GLOBAL OVERLAYS */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                />
            )}

            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}

            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onWatchAd={handleWatchAd} 
                    onGoPlay={handleGoPlay} 
                />
            )}

            {isWatchingAd && <AdOverlay />}

            {activeTooltip && (
                <SkillTooltip 
                    {...activeTooltip}
                />
            )}

          </div>
      </>
  );
}

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';
import { sounds } from './utils/sound';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop';

// Define Level Counts
const getLevelCount = (diff: Difficulty) => {
    return 100;
};

const getDifficultyPoints = (diff: Difficulty) => {
    switch(diff) {
        case Difficulty.SuperEasy: return 5;
        case Difficulty.Easy: return 10;
        case Difficulty.Normal: return 15;
        case Difficulty.Hard: return 20;
        case Difficulty.Intense: return 30;
        case Difficulty.Impossible: return 50;
        default: return 0;
    }
};

// --- DATA: Regular Store Items ---
const STATIC_BACKGROUNDS = [
    { id: 'bg-default', name: 'Default', cost: 0, class: 'bg-paper dark:bg-stone-900' },
    { id: 'bg-dawn', name: 'Dawn', cost: 100, class: 'bg-gradient-to-br from-orange-50 to-rose-50' },
