// --- Unlock Card Component ---
interface UnlockCardProps {
    difficulty: Difficulty;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

const UnlockCard: React.FC<UnlockCardProps> = ({ difficulty, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));
    const isCompleted = rawPercent === 100;

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            let start = 0;
            const duration = 1500;
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = 1 - Math.pow(1 - progress, 3); // Cubic ease out

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!isCompleted) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-6 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!isCompleted}
                className={`w-full aspect-[2/1] rounded-3xl relative overflow-hidden transition-all duration-300 ${isCompleted ? 'bg-t-surface shadow-lg active:scale-95 border-2 border-blue-500' : 'bg-stone-200 dark:bg-stone-800 cursor-default opacity-80 grayscale'}`}
            >
                {/* Content */}
                <div className="absolute inset-0 flex flex-col items-center justify-center p-6">
                    {isCompleted ? (
                        <div className="flex flex-col items-center gap-3 animate-fade-in">
                            <Icons.LockOpen className="w-10 h-10 text-blue-500" />
                            <div className="flex items-center gap-2 bg-blue-50 dark:bg-blue-900/30 px-4 py-2 rounded-xl">
                                <span className="text-sm font-bold text-stone-700 dark:text-blue-100">Unlock next 100 levels —</span>
                                <span className="text-lg font-bold text-stone-900 dark:text-white flex items-center gap-1">
                                    {cost} <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                </span>
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col items-center gap-4 w-full max-w-[200px]">
                            <Icons.Lock className="w-12 h-12 text-stone-400 dark:text-stone-600" />

                            <div className="w-full flex flex-col items-center gap-2">
                                <div className="text-4xl font-black text-stone-400 dark:text-stone-600 tabular-nums">
                                    {animatedPercent}%
                                </div>
                                {/* Progress Bar */}
                                <div className="w-full h-2 bg-stone-300 dark:bg-stone-700 rounded-full overflow-hidden">
                                    <div 
                                        className="h-full bg-stone-500 transition-all duration-75 ease-out" 
                                        style={{ width: `${animatedPercent}%` }}
                                    />
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

