// --- Unlock Card Component ---
interface UnlockCardProps {
    difficulty: Difficulty;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

const UnlockCard: React.FC<UnlockCardProps> = ({ difficulty, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));
    const isCompleted = rawPercent === 100;

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            let start = 0;
            const duration = 1500;
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = 1 - Math.pow(1 - progress, 3); // Cubic ease out

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!isCompleted) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-6 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!isCompleted}
                className={`w-full h-36 rounded-3xl relative overflow-hidden transition-all duration-300 ${isCompleted ? 'bg-t-surface shadow-lg active:scale-95 border-2 border-blue-500' : 'bg-stone-200 dark:bg-stone-800 cursor-default opacity-80 grayscale'}`}
            >
                {/* Content */}
                <div className="absolute inset-0 flex items-center justify-center p-6">
                    {isCompleted ? (
                        <div className="flex flex-row items-center gap-6 animate-fade-in">
                            <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-full">
                                <Icons.LockOpen className="w-8 h-8 text-blue-500" />
                            </div>
                            <div className="flex flex-col items-start gap-1">
                                <span className="text-sm font-bold text-stone-500 dark:text-stone-400 uppercase tracking-wider">Unlock Levels 101-200</span>
                                <span className="text-2xl font-bold text-stone-900 dark:text-white flex items-center gap-2">
                                    {cost} <Icons.Diamond className="w-5 h-5 text-blue-500 fill-current" />
                                </span>
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-row items-center justify-between w-full max-w-xs gap-6">
                            <Icons.Lock className="w-12 h-12 text-stone-400 dark:text-stone-600 flex-shrink-0" />

                            <div className="flex-1 flex flex-col items-end gap-2">
                                <div className="text-4xl font-black text-stone-400 dark:text-stone-600 tabular-nums leading-none">
                                    {animatedPercent}%
                                </div>
                                {/* Progress Bar */}
                                <div className="w-full h-2.5 bg-stone-300 dark:bg-stone-700 rounded-full overflow-hidden">
                                    <div 
                                        className="h-full bg-stone-500 transition-all duration-75 ease-out" 
                                        style={{ width: `${animatedPercent}%` }}
                                    />
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

