    // Check storage for unlocked packs. Base is 100.
    const isPack2Unlocked = Storage.isPack2Unlocked(diff);
    return isPack2Unlocked ? 200 : 100;
};

const getDifficultyPoints = (diff: Difficulty) => {
    switch(diff) {
        case Difficulty.SuperEasy: return 5;
        case Difficulty.Easy: return 10;
        case Difficulty.Normal: return 15;
        case Difficulty.Hard: return 20;
        case Difficulty.Intense: return 30;
        case Difficulty.Impossible: return 50;
        default: return 0;
    }
};

// --- Unlock Card Component ---
interface UnlockCardProps {
    difficulty: Difficulty;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

const UnlockCard: React.FC<UnlockCardProps> = ({ difficulty, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);
    const [showUnlockUI, setShowUnlockUI] = useState(false);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                    setShowUnlockUI(false); // Reset UI state
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            const duration = 2500; // Slower duration
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = progress; // Linear easing

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                    if (rawPercent === 100) {
                        // Wait a moment after hitting 100% before showing the unlock button
                        setTimeout(() => {
                            setShowUnlockUI(true);
                        }, 500);
                    }
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!showUnlockUI) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-6 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!showUnlockUI}
                className={`w-full h-44 rounded-3xl relative overflow-hidden transition-all duration-300 group ${
                    showUnlockUI 
                        ? 'bg-t-surface shadow-xl active:scale-95 border-2 border-blue-500 cursor-pointer' 
                        : 'bg-stone-200 dark:bg-stone-800 cursor-default'
                }`}
            >
                {/* Content */}
                <div className="absolute inset-0 flex items-center justify-center p-6">
                    {showUnlockUI ? (
                        <div className="flex flex-col items-center justify-center w-full animate-fade-in gap-3">
                             <div className="flex items-center gap-2 mb-1">
                                <div className="p-1.5 bg-blue-100 dark:bg-blue-900/40 rounded-lg">
                                    <Icons.LockOpen className="w-4 h-4 text-blue-600 dark:text-blue-400" />
                                </div>
                                <span className="text-sm font-bold text-stone-500 dark:text-stone-400 uppercase tracking-widest">
                                    Unlock Levels 101-200
                                </span>
                             </div>

                             <div className="flex items-center gap-3 scale-110">
                                <span className="text-6xl font-black text-stone-900 dark:text-white tracking-tighter">
                                    {cost}
                                </span>
                                <Icons.Diamond className="w-10 h-10 text-blue-500 fill-current drop-shadow-sm group-hover:scale-110 transition-transform" />
                             </div>

                             <div className="h-1 w-16 bg-blue-500/20 rounded-full overflow-hidden mt-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                 <div className="h-full w-full bg-blue-500 animate-pulse" />
                             </div>
                        </div>
                    ) : (
                        <div className="flex flex-row items-center justify-between w-full max-w-xs gap-8">
                            {/* Left Side: Lock Icon */}
                            <div className="w-20 h-20 rounded-2xl bg-stone-300/50 dark:bg-stone-700/50 flex items-center justify-center shadow-inner">
                                <Icons.Lock className="w-9 h-9 text-stone-500 dark:text-stone-500" />
                            </div>

                            {/* Right Side: Progress */}
                            <div className="flex-1 flex flex-col items-start gap-3">
                                <div className="flex items-baseline gap-1">
                                    <span className="text-5xl font-black text-stone-500 dark:text-stone-400 tabular-nums leading-none">
                                        {animatedPercent}
                                    </span>
                                    <span className="text-xl font-bold text-stone-400 dark:text-stone-500">%</span>
                                </div>
                                {/* Progress Bar */}
                                <div className="w-full h-3.5 bg-stone-300 dark:bg-stone-700 rounded-full overflow-hidden shadow-inner">
                                    <div 
                                        className="h-full bg-loading-green transition-all duration-100 ease-linear" 
                                        style={{ width: `${animatedPercent}%` }}
                                    />
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

