                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                                  <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-t-secondary font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                      <div className="mb-6">
                                          <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                                          <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                              const isPurchased = purchasedBackgrounds.includes(bg.id);
                                              const isSelected = selectedBackgroundId === bg.id;
                                              return (
                                                  <div key={bg.id} className="flex flex-col items-center gap-1">
                                                      <button onClick={() => isPurchased ? handleSelectBackground(bg.id) : initiatePurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isPurchased ? 'opacity-90' : ''}`}>
                                                          <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                                          {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                                          {!isPurchased && (
                                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                                  <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                              </div>
                                                          )}
                                                      </button>
                                                      <span className="text-[10px] text-t-secondary font-medium truncate w-full text-center">{bg.name}</span>
                                                  </div>
                                              );
                                          })}</div>
                                      </div>
                                  </div>

                                  {/* NUMBER COLORS */}
                                  <div>
                                      <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                                      <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                                          const isPurchased = purchasedNumberColors.includes(num.id);
                                          const isSelected = selectedNumberColorId === num.id;
                                          return (
                                              <div key={num.id} className="flex flex-col items-center gap-1">
                                                  <button onClick={() => isPurchased ? handleSelectNumberColor(num.id) : initiatePurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                                      <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                                          <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                                      </div>
                                                      {!isPurchased && (
                                                          <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                              <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      )}
                                                  </button>
                                                  <span className="text-[10px] text-t-secondary font-medium truncate w-full text-center">{num.name}</span>
                                              </div>
                                          );
                                      })}</div>
                                  </div>

                                  {/* INFO */}
                                  <div className="text-center pt-4 pb-8">
                                      <p className="text-xs text-t-secondary max-w-xs mx-auto">
                                          Unlock backgrounds and styles using diamonds earned by playing.
                                      </p>
                                  </div>
                              </div>
                              <div className="h-safe-bottom w-full shrink-0" />
                         </div>
                    </div>
                )}

                {/* GAME */}
                {screen === 'game' && selectedDifficulty && selectedLevel && (
                    <SudokuGame
                        difficulty={selectedDifficulty}
                        levelId={selectedLevel}
                        onBack={handleGameBack}
                        onReturnToMenu={handleReturnToMenu}
                        onComplete={() => {
                            setPoints(Storage.getPoints());
                        }}
                        onNextLevel={() => {
                            const nextLevel = selectedLevel + 1;
                            const isPack2Unlocked = Storage.isPack2Unlocked(selectedDifficulty);
                            const maxLevel = isPack2Unlocked ? 200 : 100;

                            // Check if next level is within bounds
                            if (nextLevel <= maxLevel) {
                                handleLevelSelect(nextLevel);
                            } else {
                                handleReturnToMenu();
                            }
                        }}
                        onSettingsOpen={() => setShowSettings(true)}
                        settings={settings}
                        onEarnPoints={handleEarnPoints}
                        currentPoints={points}
                        isSettingsOpen={showSettings}
                        backgroundClass={activeBackgroundClass}
                        numberColor={numberColorClass}
                        purchasedSkills={purchasedSkills}
                    />
                )}
            </div>

            {/* GLOBAL OVERLAYS */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                />
            )}

            {/* Replay Modal */}
            {replayLevelId !== null && selectedDifficulty && (
                <ReplayModal 
                    levelId={replayLevelId}
                    onConfirm={confirmReplay}
                    onCancel={() => setReplayLevelId(null)}
                />
            )}

            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}

            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onWatchAd={handleWatchAd} 
                    onGoPlay={handleGoPlay} 
                />
            )}

            {isWatchingAd && <AdOverlay />}

            {activeTooltip && (
                <SkillTooltip 
                    {...activeTooltip}
                />
            )}

          </div>
      </>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';
import { sounds } from './utils/sound';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop';

const PACK_2_COSTS = {
    [Difficulty.SuperEasy]: 700,
    [Difficulty.Easy]: 900,
    [Difficulty.Normal]: 1200,
    [Difficulty.Hard]: 1500,
    [Difficulty.Intense]: 1800,
    [Difficulty.Impossible]: 2200,
};

// Define Level Counts
const getLevelCount = (diff: Difficulty) => {
    // Check storage for unlocked packs. Base is 100.
    const isPack2Unlocked = Storage.isPack2Unlocked(diff);
    return isPack2Unlocked ? 200 : 100;
};

const getDifficultyPoints = (diff: Difficulty) => {
    switch(diff) {
        case Difficulty.SuperEasy: return 5;
        case Difficulty.Easy: return 10;
        case Difficulty.Normal: return 15;
        case Difficulty.Hard: return 20;
        case Difficulty.Intense: return 30;
        case Difficulty.Impossible: return 50;
        default: return 0;
    }
};

// --- Unlock Card Component ---
interface UnlockCardProps {
    difficulty: Difficulty;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

const UnlockCard: React.FC<UnlockCardProps> = ({ difficulty, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);
    const [showUnlockUI, setShowUnlockUI] = useState(false);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                    setShowUnlockUI(false); // Reset UI state
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            const duration = 2500; // Slower duration
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = progress; // Linear easing

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                    if (rawPercent === 100) {
                        // Wait a moment after hitting 100% before showing the unlock button
                        setTimeout(() => {
                            setShowUnlockUI(true);
                        }, 500);
                    }
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!showUnlockUI) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-8 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!showUnlockUI}
                className={`w-full h-52 rounded-[2rem] relative overflow-hidden transition-all duration-500 ease-out group ${
                    showUnlockUI 
                        ? 'bg-gradient-to-b from-white to-blue-50/50 dark:from-stone-800 dark:to-stone-900 shadow-[0_20px_40px_-15px_rgba(59,130,246,0.15)] active:scale-[0.98] border border-blue-100 dark:border-blue-900/30 cursor-pointer' 
                        : 'bg-stone-100 dark:bg-stone-800/40 cursor-default border border-transparent'
                }`}
            >
                {/* Background Decor for Unlock State */}
                {showUnlockUI && (
                    <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-700">
                        <div className="absolute -top-24 -right-24 w-48 h-48 bg-blue-400/10 rounded-full blur-3xl"></div>
                        <div className="absolute -bottom-24 -left-24 w-48 h-48 bg-indigo-400/10 rounded-full blur-3xl"></div>
                    </div>
                )}

                {/* Content Container */}
                <div className="absolute inset-0 flex items-center justify-center p-6">
                    {showUnlockUI ? (
                        <div className="flex flex-col items-center justify-center w-full animate-fade-in h-full relative z-10">

                             {/* Header Pill */}
                             <div className="mb-auto mt-2">
                                 <div className="flex items-center gap-2 px-4 py-1.5 bg-white dark:bg-stone-800 rounded-full shadow-sm border border-stone-100 dark:border-stone-700">
                                    <Icons.LockOpen className="w-3.5 h-3.5 text-blue-500" />
                                    <span className="text-[10px] font-bold text-stone-400 dark:text-stone-500 uppercase tracking-[0.15em] pt-0.5">
                                        Levels 101-200
                                    </span>
                                 </div>
                             </div>

                             {/* Main Price */}
                             <div className="flex items-center gap-3 mb-auto pb-4 transform transition-transform duration-300 group-hover:scale-110">
                                <span className="text-7xl font-black text-stone-900 dark:text-white tracking-tighter leading-none" style={{ fontVariantNumeric: 'tabular-nums' }}>
                                    {cost}
                                </span>
                                <div className="relative">
                                    <Icons.Diamond className="w-12 h-12 text-blue-500 fill-current drop-shadow-md" />
                                    {/* Sparkles */}
                                    <div className="absolute -top-1 -right-1 w-2 h-2 bg-white rounded-full animate-ping opacity-75"></div>
                                </div>
                             </div>

                             {/* Bottom Indicator */}
                             <div className="absolute bottom-4 flex flex-col items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-2 group-hover:translate-y-0">
                                 <span className="text-[10px] font-bold text-blue-500 uppercase tracking-widest">Tap to Unlock</span>
                             </div>
                        </div>
                    ) : (
                        <div className="flex flex-row items-center justify-between w-full max-w-xs gap-8 px-2">
                            {/* Left Side: Lock Icon with Container */}
                            <div className="w-20 h-20 rounded-2xl bg-stone-200 dark:bg-stone-700/50 flex items-center justify-center shadow-inner relative overflow-hidden group-hover:bg-stone-300/50 transition-colors">
