function formatTimeShort(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [isLongTransition, setIsLongTransition] = useState(false);
  const [isMediumTransition, setIsMediumTransition] = useState(false);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill', description?: string} | null>(null);
  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [bonusClaimed, setBonusClaimed] = useState(Storage.isBonusClaimed());

  // State for skill description tooltip in Store
  const [activeTooltip, setActiveTooltip] = useState<TooltipData | null>(null);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };

      applyTheme();

      // Listen for system changes if mode is system
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  // Attempt to lock screen orientation to portrait on mount
  useEffect(() => {
    const lockOrientation = async () => {
      try {
        if (window.screen && window.screen.orientation && typeof (window.screen.orientation as any).lock === 'function') {
           await (window.screen.orientation as any).lock('portrait').catch(() => {
               // Silently fail if lock is not supported or allowed (e.g. not fullscreen)
           });
        }
      } catch (e) {
        // Ignore errors
      }
    };
    lockOrientation();
  }, []);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
  }, [settings.sound, settings.vibration]);

  useEffect(() => {
    const timer = setTimeout(() => setScreen('difficulty'), 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());

     // Reset store interaction state on screen change
     setActiveTooltip(null);
  }, [screen]);

  // Update theme color meta tag to match background to prevent white/black bars in some contexts
  useEffect(() => {
      // Re-apply theme color based on current mode
      const isDark = document.documentElement.classList.contains('dark');
      const meta = document.querySelector('meta[name="theme-color"]');
      if (meta) {
          meta.setAttribute('content', isDark ? '#1c1917' : '#fafaf9'); 
      }
  }, [selectedBackgroundId, settings.appearance]);

  const transitionTo = (nextScreen: Screen, type: 'short' | 'medium' | 'long' = 'short') => {
      if (type === 'long') setIsLongTransition(true);
      else if (type === 'medium') setIsMediumTransition(true);
      else { setIsLongTransition(false); setIsMediumTransition(false); }

      setIsTransitioning(true);
      setTimeout(() => {
          setScreen(nextScreen);
          setPoints(Storage.getPoints());
          setIsTransitioning(false);
      }, type === 'long' ? 1000 : (type === 'medium' ? 500 : 300));
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    transitionTo('levels', 'medium');
  };

  const handleLevelBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleGameBack = () => { sounds.playClick(); transitionTo('levels', 'medium'); };
  const handleReturnToMenu = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleStoreBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleDiamondShopBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        transitionTo('game', 'medium');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          transitionTo('game', 'medium');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = () => {
    if (bonusClaimed) return;
    sounds.playWin();
    Storage.setBonusClaimed();
    setBonusClaimed(true);
    handleEarnPoints(5000);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill') => {
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills([...purchasedSkills, purchaseCandidate.id]);
             }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          // Not enough points
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(10);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          transitionTo('difficulty', 'medium');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.id === 'starter_pack' && starterPackPurchased) return;

      alert(`In-App Purchases are not connected yet.\n\nBuying: ${offer.title}`);
  };

  const handleSkillClick = (e: React.MouseEvent<HTMLButtonElement>, skill: typeof SKILLS[0]) => {
      e.stopPropagation();
      if (activeTooltip?.id === skill.id) {
          sounds.playClick();
          setActiveTooltip({ ...activeTooltip, isClosing: true });
          setTimeout(() => setActiveTooltip(null), 200); // Wait for anim
      } else {
          sounds.playClick();
          const rect = e.currentTarget.getBoundingClientRect();
          const x = rect.left + rect.width / 2;
          const y = rect.top - 8; // Slight padding above the icon

          setActiveTooltip({
              id: skill.id,
              x,
              y,
              text: skill.description,
              isClosing: false
          });
      }
  };

  const handleDismissTooltip = () => {
      if (activeTooltip && !activeTooltip.isClosing) {
          setActiveTooltip({ ...activeTooltip, isClosing: true });
          setTimeout(() => setActiveTooltip(null), 200);
      }
  };

  // Pack Unlock Handlers
  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = PACK_2_COSTS[selectedDifficulty];
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = PACK_3_COSTS[selectedDifficulty];
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  // Determine Background Logic
  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; // Default for Menu, Levels, Store, Settings

  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50 dark:bg-stone-900"; // Splash is special, handled in component
  } else if (screen === 'game') {
      // ONLY show custom background in Game
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  // Dynamic transition classes
  const transitionDuration = isLongTransition ? 'duration-1000' : (isMediumTransition ? 'duration-500' : 'duration-300');
  // Fade background out and in for long and medium transitions to avoid flashes on navigation
  const bgOpacity = (isTransitioning && (isLongTransition || isMediumTransition)) ? 'opacity-0' : 'opacity-100';

  // Overlay Logic to darken game screen in dark mode
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';

  if (isGradient) {
      if (screen === 'game') {
          // Custom backgrounds in Game Mode: 80% opacity (0.5 * 1.6 = 0.8 in dark mode)
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          // Gradients get standard dark overlay elsewhere
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      // Default background gets 30% dim in game mode (calculated from 0.5 base)
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // --- Main Render with Strict Layer Architecture ---
  return (
      <>
          {/* LAYER 1: Background - Fixed, Full Screen, Z-Index 0 */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out ${activeBackgroundClass} ${transitionDuration} ${bgOpacity}`} 
            style={{ width: '100%', height: '100%' }}
          />

          {/* LAYER 1.5: Dark Mode Overlay - Adds darkness to any background */}
          <div 
            className="fixed inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
