function formatTimeShort(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [isLongTransition, setIsLongTransition] = useState(false);
  const [isMediumTransition, setIsMediumTransition] = useState(false);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill', description?: string} | null>(null);
  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [bonusClaimed, setBonusClaimed] = useState(Storage.isBonusClaimed());

  // State for skill description tooltip in Store
  const [activeTooltip, setActiveTooltip] = useState<TooltipData | null>(null);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };

      applyTheme();

      // Listen for system changes if mode is system
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  // Attempt to lock screen orientation to portrait on mount
  useEffect(() => {
    const lockOrientation = async () => {
      try {
        if (window.screen && window.screen.orientation && typeof (window.screen.orientation as any).lock === 'function') {
           await (window.screen.orientation as any).lock('portrait').catch(() => {
               // Silently fail if lock is not supported or allowed (e.g. not fullscreen)
           });
        }
      } catch (e) {
        // Ignore errors
      }
    };
    lockOrientation();
  }, []);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
  }, [settings.sound, settings.vibration]);

  useEffect(() => {
    const timer = setTimeout(() => setScreen('difficulty'), 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());

     // Reset store interaction state on screen change
     setActiveTooltip(null);
  }, [screen]);

  // Update theme color meta tag to match background to prevent white/black bars in some contexts
  useEffect(() => {
      // Re-apply theme color based on current mode
      const isDark = document.documentElement.classList.contains('dark');
      const meta = document.querySelector('meta[name="theme-color"]');
      if (meta) {
          meta.setAttribute('content', isDark ? '#1c1917' : '#fafaf9'); 
      }
  }, [selectedBackgroundId, settings.appearance]);

  const transitionTo = (nextScreen: Screen, type: 'short' | 'medium' | 'long' = 'short') => {
      if (type === 'long') setIsLongTransition(true);
      else if (type === 'medium') setIsMediumTransition(true);
      else { setIsLongTransition(false); setIsMediumTransition(false); }

      setIsTransitioning(true);
      setTimeout(() => {
          setScreen(nextScreen);
          setPoints(Storage.getPoints());
          setIsTransitioning(false);
      }, type === 'long' ? 1000 : (type === 'medium' ? 500 : 300));
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    transitionTo('levels', 'medium');
  };

  const handleLevelBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleGameBack = () => { sounds.playClick(); transitionTo('levels', 'medium'); };
  const handleReturnToMenu = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleStoreBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };
  const handleDiamondShopBack = () => { sounds.playClick(); transitionTo('difficulty', 'medium'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();

        // FADE OUT current view completely
        setIsMediumTransition(true); 

        // Wait for fade-out to complete (500ms for 'medium'), then swap content
        setTimeout(() => {
            setSelectedLevel(levelId);
            setScreen('game');
            // The new component will animate in itself or we can fade container back in
            // For smoother cross-fade where new component also animates:
            setIsMediumTransition(false); 
        }, 500); 
    }
  };

  const handleReplayConfirm = () => {
      if (replayLevelId !== null && selectedDifficulty) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);

          sounds.playLevelEnter();
          setIsMediumTransition(true);
          setTimeout(() => {
              setSelectedLevel(replayLevelId);
              setScreen('game');
              setIsMediumTransition(false);
          }, 500);
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
      const newSettings = { ...settings, [key]: !settings[key] };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
      sounds.playClick();
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const handleReset = () => {
      if (confirm('Are you sure you want to reset all progress and points? This cannot be undone.')) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleEarnPoints = (amount: number) => {
      const newTotal = Storage.addPoints(amount);
      setPoints(newTotal);
  };

  const handleStorePurchase = (item: any, type: 'bg' | 'num' | 'skill') => {
      sounds.playClick();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;

      let success = false;
      if (purchaseCandidate.type === 'bg') {
          success = Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
              Storage.selectBackground(purchaseCandidate.id);
              setSelectedBackgroundId(purchaseCandidate.id);
          }
      } else if (purchaseCandidate.type === 'num') {
          success = Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedNumberColors(Storage.getPurchasedNumberColors());
              Storage.selectNumberColor(purchaseCandidate.id);
              setSelectedNumberColorId(purchaseCandidate.id);
          }
      } else if (purchaseCandidate.type === 'skill') {
          success = Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedSkills(Storage.getPurchasedSkills());
          }
      }

      setPurchaseCandidate(null);

      if (success) {
          sounds.playPop();
          setPoints(Storage.getPoints());
      } else {
          setShowNotEnoughPoints(true);
      }
  };

  const handleSelectBackground = (id: string | null) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleDailyBonus = () => {
      if (!bonusClaimed) {
          sounds.playPop();
          Storage.addPoints(50);
          Storage.setBonusClaimed();
          setBonusClaimed(true);
          setPoints(Storage.getPoints());
      }
  };

  const handleWatchAd = () => {
      setShowNotEnoughPoints(false);
      setIsWatchingAd(true);
      setTimeout(() => {
          setIsWatchingAd(false);
          sounds.playPop();
          Storage.addPoints(10);
          setPoints(Storage.getPoints());
      }, 3000); // Fake ad duration
  };

  const handlePackUnlock = (difficulty: string, range: 'pack2' | 'pack3', cost: number) => {
      let success = false;
      if (range === 'pack2') {
          success = Storage.unlockPack2(difficulty, cost);
          if (success) setUnlockedPacks2(Storage.getUnlockedPacks2());
      } else {
          success = Storage.unlockPack3(difficulty, cost);
          if (success) setUnlockedPacks3(Storage.getUnlockedPacks3());
      }

      if (success) {
          sounds.playPop();
          setPoints(Storage.getPoints());
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  // Render Helpers
  const renderBackgroundClass = () => {
      const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
      return bg ? bg.class : 'bg-paper dark:bg-stone-900';
  };

  const renderNumberColorClass = () => {
      const nc = NUMBER_COLORS.find(c => c.id === selectedNumberColorId);
      return nc ? nc.class : 'text-blue-600';
  };

  return (
    <div className={`w-full h-full relative overflow-hidden flex flex-col transition-colors duration-500 ${renderBackgroundClass()}`}>
      {/* Background Overlay for Transitions - Matches App Background Logic */}
      <div className={`fixed inset-0 pointer-events-none z-[100] transition-opacity ${
          isTransitioning 
            ? (isLongTransition ? 'duration-1000' : (isMediumTransition ? 'duration-500' : 'duration-300')) 
            : 'duration-300'
          } ${isTransitioning ? 'opacity-100 bg-white dark:bg-stone-950' : 'opacity-0'}`} 
      />

      {/* Replay Modal */}
      {replayLevelId !== null && (
          <ReplayModal 
            levelId={replayLevelId} 
            onConfirm={handleReplayConfirm} 
            onCancel={() => { sounds.playClick(); setReplayLevelId(null); }} 
          />
      )}

      {/* Purchase Modal */}
      {purchaseCandidate && (
          <PurchaseModal 
            item={purchaseCandidate} 
            onConfirm={confirmPurchase} 
            onCancel={() => { sounds.playClick(); setPurchaseCandidate(null); }} 
          />
      )}

      {/* Not Enough Points Modal */}
      {showNotEnoughPoints && (
          <NotEnoughPointsModal 
            onClose={() => { sounds.playClick(); setShowNotEnoughPoints(false); }}
            onWatchAd={handleWatchAd}
            onGoPlay={() => { sounds.playClick(); setShowNotEnoughPoints(false); transitionTo('difficulty', 'medium'); }}
          />
      )}

      {/* Settings Modal */}
      {showSettings && (
          <SettingsModal 
            settings={settings}
            onToggle={toggleSetting}
            onSetAppearance={setAppearance}
            onReset={handleReset}
            onClose={() => setShowSettings(false)}
          />
      )}

      {/* Fake Ad Overlay */}
      {isWatchingAd && <AdOverlay />}

      {screen === 'splash' && (
        <div className="flex-1 flex flex-col items-center justify-center animate-fade-in relative z-10">
           <div className="w-24 h-24 mb-6 rounded-3xl bg-stone-800 flex items-center justify-center shadow-2xl relative overflow-hidden">
               {/* Icon visual */}
               <div className="absolute inset-0 bg-gradient-to-br from-stone-700 to-stone-900"></div>
               <div className="grid grid-cols-3 gap-1 p-2 relative z-10 opacity-90">
                   <div className="w-5 h-5 bg-white/10 rounded-md"></div><div className="w-5 h-5 bg-white/90 rounded-md"></div><div className="w-5 h-5 bg-white/10 rounded-md"></div>
                   <div className="w-5 h-5 bg-white/90 rounded-md"></div><div className="w-5 h-5 bg-blue-500 rounded-md shadow-lg shadow-blue-500/50"></div><div className="w-5 h-5 bg-white/90 rounded-md"></div>
                   <div className="w-5 h-5 bg-white/10 rounded-md"></div><div className="w-5 h-5 bg-white/90 rounded-md"></div><div className="w-5 h-5 bg-white/10 rounded-md"></div>
               </div>
           </div>
           <h1 className="text-3xl font-light tracking-[0.2em] text-stone-800 dark:text-stone-200">SUDOKU</h1>
        </div>
      )}

      {screen === 'difficulty' && (
        <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in relative z-10">
          <div className="w-full max-w-sm">
            <h2 className="text-3xl font-light text-t-primary text-center mb-10 tracking-widest">SELECT LEVEL</h2>
            <div className="grid grid-cols-2 gap-4">
              {Object.values(Difficulty).map((diff) => (
                <button
                  key={diff}
                  onClick={() => handleDifficultySelect(diff)}
                  className="bg-t-surface border-2 border-t-border hover:border-stone-400 dark:hover:border-stone-500 text-t-primary py-6 rounded-2xl transition-all active:scale-[0.98] shadow-sm flex flex-col items-center gap-2 group"
                >
                  <span className="text-lg font-medium tracking-wide group-hover:tracking-wider transition-all">{diff}</span>
                  <div className="flex gap-1">
                      {/* Difficulty Dots Visual */}
                      {[...Array(3)].map((_, i) => (
                          <div key={i} className={`w-1.5 h-1.5 rounded-full ${
                              (diff === Difficulty.SuperEasy && i === 0) ? 'bg-green-400' :
                              (diff === Difficulty.Easy && i === 0) ? 'bg-blue-400' :
                              (diff === Difficulty.Normal && i <= 1) ? 'bg-yellow-400' :
                              (diff === Difficulty.Hard && i <= 2) ? 'bg-orange-400' :
                              (diff === Difficulty.Intense && i <= 2) ? 'bg-red-500' :
                              (diff === Difficulty.Impossible && i <= 2) ? 'bg-purple-600' :
                              'bg-stone-200 dark:bg-stone-700'
                          }`} />
                      ))}
                  </div>
                </button>
              ))}
            </div>

            {/* Store & Diamond Buttons */}
            <div className="mt-12 grid grid-cols-2 gap-4">
                <button 
                    onClick={() => { sounds.playClick(); transitionTo('store', 'medium'); }}
                    className="bg-t-surface text-t-primary py-4 rounded-xl shadow-md border border-t-border flex items-center justify-center gap-2 active:scale-95 transition"
                >
                    <Icons.Store className="w-5 h-5 text-t-icon" />
                    <span className="font-bold text-sm">Store</span>
                </button>
                <button 
                    onClick={() => { sounds.playClick(); transitionTo('diamondShop', 'medium'); }}
                    className="bg-stone-800 text-white dark:bg-blue-600 dark:text-white py-4 rounded-xl shadow-lg flex items-center justify-center gap-2 active:scale-95 transition"
                >
                    <Icons.Diamond className="w-4 h-4 fill-current text-blue-300 dark:text-blue-200" />
                    <span className="font-bold text-sm">Get Gems</span>
                </button>
            </div>

            {/* Daily Bonus Button - Only show if not claimed */}
            {!bonusClaimed && (
                <button 
                    onClick={handleDailyBonus}
                    className="mt-4 w-full py-4 bg-gradient-to-r from-amber-100 to-orange-100 dark:from-amber-900/30 dark:to-orange-900/30 border border-amber-200 dark:border-amber-800 text-amber-800 dark:text-amber-200 rounded-xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition animate-pulse"
                >
                    <Icons.Gift className="w-5 h-5" />
                    <span className="font-bold text-sm">Claim Daily Bonus (+50)</span>
                </button>
            )}

            <div className="mt-8 flex justify-center">
                 <div className="flex items-center gap-1 bg-t-surface-sec px-4 py-2 rounded-full shadow-inner">
                    <div className="text-blue-500"><Icons.Diamond className="w-4 h-4 fill-current" /></div>
                    <span className="text-sm font-bold text-t-primary tabular-nums">{points}</span>
                </div>
            </div>

            <button onClick={() => { sounds.playClick(); setShowSettings(true); }} className="mt-8 mx-auto p-3 text-t-secondary hover:text-t-primary transition rounded-full hover:bg-t-surface-sec">
                <Icons.Settings className="w-6 h-6" />
            </button>
          </div>
        </div>
