      {screen === 'levels' && selectedDifficulty && (
        <div className="flex-1 flex flex-col h-full animate-fade-in relative z-10">
          <div className="p-6 pb-2 flex items-center justify-between bg-t-bg z-20">
            <button onClick={handleLevelBack} className="p-2 rounded-full hover:bg-stone-200 dark:hover:bg-stone-800 transition -ml-2">
                <Icons.Back className="w-6 h-6 text-t-icon" />
