            <h2 className="text-xl font-bold tracking-widest text-t-primary uppercase">{selectedDifficulty}</h2>
            <div className="flex items-center gap-1 bg-t-surface-sec px-3 py-1.5 rounded-full">
                <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                <span className="text-xs font-bold text-t-primary tabular-nums">{points}</span>
            </div>
          </div>

