                <div className="grid grid-cols-5 gap-3">
                  {Array.from({ length: 100 }, (_, i) => i + 1).map((level) => {
                    const progress = Storage.getLevelProgress(selectedDifficulty, level);
                    const isCompleted = progress?.status === 'completed';
                    const isLocked = false; 
                    const isCurrent = !isCompleted && (level === 1 || Storage.getLevelProgress(selectedDifficulty, level - 1)?.status === 'completed');

                    return (
                      <button
                        key={level}
                        onClick={() => handleLevelSelect(level)}
                        className={`aspect-square rounded-xl flex items-center justify-center text-sm font-bold shadow-sm transition-all active:scale-95 relative overflow-hidden ${
                          isCompleted 
                            ? 'bg-stone-800 text-white dark:bg-t-primary dark:text-stone-900' 
                            : isCurrent
                            ? 'bg-blue-500 text-white ring-4 ring-blue-200 dark:ring-blue-900'
                            : 'bg-t-surface text-t-primary border border-t-border'
                        }`}
                      >
                        {level}
                        {progress?.bestTime && (
                            <div className="absolute bottom-0.5 w-1 h-1 bg-white/50 rounded-full"></div>
                        )}
                      </button>
                    );
                  })}
                </div>
            </div>

            {/* Pack 2: Levels 101-200 */}
            <div className="mb-6 relative">
                 <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-4 sticky top-0 bg-t-bg py-2 z-10 flex justify-between items-center">
                    <span>Pack 2 (101-200)</span>
                    {!unlockedPacks2.includes(selectedDifficulty) && <Icons.Lock className="w-3 h-3" />}
                 </h3>

                 {!unlockedPacks2.includes(selectedDifficulty) ? (
                     <UnlockCard 
                        startLevel={101}
                        endLevel={200}
                        completedCount={Storage.getCompletedCountInRange(selectedDifficulty, 1, 100)}
                        totalBaseLevels={100}
                        cost={PACK_2_COSTS[selectedDifficulty]}
                        onUnlock={() => handlePackUnlock(selectedDifficulty, 'pack2', PACK_2_COSTS[selectedDifficulty])}
                     />
                 ) : (
                    <div className="grid grid-cols-5 gap-3 animate-fade-in">
                      {Array.from({ length: 100 }, (_, i) => i + 101).map((level) => {
                        const progress = Storage.getLevelProgress(selectedDifficulty, level);
                        const isCompleted = progress?.status === 'completed';
                        // For unlocked pack, first level is available, or if prev is completed
                        const isUnlocked = level === 101 || Storage.getLevelProgress(selectedDifficulty, level - 1)?.status === 'completed';

                        return (
                          <button
                            key={level}
                            disabled={!isUnlocked && !isCompleted}
                            onClick={() => (isUnlocked || isCompleted) && handleLevelSelect(level)}
                            className={`aspect-square rounded-xl flex items-center justify-center text-sm font-bold shadow-sm transition-all active:scale-95 relative overflow-hidden ${
                              isCompleted 
                                ? 'bg-stone-800 text-white dark:bg-t-primary dark:text-stone-900' 
                                : isUnlocked
                                ? 'bg-t-surface text-t-primary border-2 border-blue-500' // Current unlocked style
                                : 'bg-t-surface-sec text-t-secondary opacity-50'
                            }`}
                          >
                             {(!isUnlocked && !isCompleted) ? <Icons.Lock className="w-3 h-3" /> : level}
                          </button>
                        );
                      })}
                    </div>
                 )}
            </div>

            {/* Pack 3: Levels 201-300 */}
            <div className="mb-6 relative">
                 <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-4 sticky top-0 bg-t-bg py-2 z-10 flex justify-between items-center">
                    <span>Pack 3 (201-300)</span>
                    {!unlockedPacks3.includes(selectedDifficulty) && <Icons.Lock className="w-3 h-3" />}
                 </h3>

                 {!unlockedPacks3.includes(selectedDifficulty) ? (
                     <UnlockCard 
                        startLevel={201}
                        endLevel={300}
                        completedCount={Storage.getCompletedCountInRange(selectedDifficulty, 101, 200)}
                        totalBaseLevels={100}
                        cost={PACK_3_COSTS[selectedDifficulty]}
                        onUnlock={() => handlePackUnlock(selectedDifficulty, 'pack3', PACK_3_COSTS[selectedDifficulty])}
                     />
                 ) : (
                    <div className="grid grid-cols-5 gap-3 animate-fade-in">
                      {Array.from({ length: 100 }, (_, i) => i + 201).map((level) => {
                        const progress = Storage.getLevelProgress(selectedDifficulty, level);
                        const isCompleted = progress?.status === 'completed';
                        const isUnlocked = level === 201 || Storage.getLevelProgress(selectedDifficulty, level - 1)?.status === 'completed';

                        return (
                          <button
                            key={level}
                            disabled={!isUnlocked && !isCompleted}
                            onClick={() => (isUnlocked || isCompleted) && handleLevelSelect(level)}
                            className={`aspect-square rounded-xl flex items-center justify-center text-sm font-bold shadow-sm transition-all active:scale-95 relative overflow-hidden ${
                              isCompleted 
                                ? 'bg-stone-800 text-white dark:bg-t-primary dark:text-stone-900' 
                                : isUnlocked
                                ? 'bg-t-surface text-t-primary border-2 border-blue-500'
                                : 'bg-t-surface-sec text-t-secondary opacity-50'
                            }`}
                          >
                            {(!isUnlocked && !isCompleted) ? <Icons.Lock className="w-3 h-3" /> : level}
                          </button>
                        );
                      })}
                    </div>
                 )}
            </div>

          </div>
        </div>
      )}

      {screen === 'game' && selectedDifficulty && selectedLevel && (
        <SudokuGame
          key={selectedLevel} // CRITICAL: Ensures remount animation on level change
          difficulty={selectedDifficulty}
          levelId={selectedLevel}
          onBack={handleGameBack}
          onReturnToMenu={handleReturnToMenu}
          onComplete={() => {}} 
          onSettingsOpen={() => setShowSettings(true)}
          onNextLevel={() => {
              if (selectedLevel) handleLevelSelect(selectedLevel + 1);
          }}
          settings={settings}
          onEarnPoints={handleEarnPoints}
          currentPoints={points}
          isSettingsOpen={showSettings}
          backgroundClass={renderBackgroundClass()}
          numberColor={renderNumberColorClass()}
          purchasedSkills={purchasedSkills}
        />
      )}

      {screen === 'store' && (
        <div className="flex-1 flex flex-col h-full animate-fade-in relative z-10">
            <div className="p-6 pb-2 flex items-center justify-between bg-t-bg z-20">
                <button onClick={handleStoreBack} className="p-2 rounded-full hover:bg-stone-200 dark:hover:bg-stone-800 transition -ml-2">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>
                <h2 className="text-xl font-bold tracking-widest text-t-primary uppercase">Store</h2>
                <div className="flex items-center gap-1 bg-t-surface-sec px-3 py-1.5 rounded-full">
                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                    <span className="text-xs font-bold text-t-primary tabular-nums">{points}</span>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 pb-20 pt-4">

                {/* Skills Section */}
                <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-4">Permanent Skills</h3>
                <div className="grid grid-cols-1 gap-3 mb-8">
                    {SKILLS.map(skill => {
                        const isOwned = purchasedSkills.includes(skill.id);
                        return (
                            <div key={skill.id} className="bg-t-surface p-4 rounded-2xl shadow-sm border border-t-border flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className={`p-3 rounded-xl bg-stone-50 dark:bg-stone-800 ${skill.class}`}>
                                        <skill.icon className="w-6 h-6" />
                                    </div>
                                    <div className="flex flex-col">
                                        <div className="flex items-center gap-2">
                                            <span className="font-bold text-t-primary">{skill.name}</span>
                                            {/* Tooltip Info Button */}
                                            <button 
                                                className="text-t-secondary hover:text-blue-500 transition-colors"
                                                onClick={(e) => {
                                                    const rect = e.currentTarget.getBoundingClientRect();
                                                    // Close if clicking same, else open new
                                                    if (activeTooltip?.id === skill.id) {
                                                        setActiveTooltip({...activeTooltip, isClosing: true});
                                                        setTimeout(() => setActiveTooltip(null), 150);
                                                    } else {
                                                        setActiveTooltip({
                                                            id: skill.id,
                                                            x: rect.left + rect.width / 2,
                                                            y: rect.top - 10,
                                                            text: skill.description,
                                                            isClosing: false
                                                        });
                                                    }
                                                }}
                                            >
                                                <Icons.Eye className="w-3.5 h-3.5" />
                                            </button>
                                        </div>
                                        <span className="text-xs text-t-secondary">Permanent unlock</span>
                                    </div>
                                </div>
                                {isOwned ? (
                                    <div className="flex items-center gap-1 text-green-500 font-bold text-xs bg-green-50 dark:bg-green-900/20 px-3 py-1.5 rounded-full">
                                        <Icons.Check className="w-3 h-3" /> Owned
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => handleStorePurchase(skill, 'skill')}
                                        className="bg-stone-800 text-white dark:bg-blue-600 px-4 py-2 rounded-xl text-sm font-bold shadow-md active:scale-95 transition flex items-center gap-1"
                                    >
                                        {skill.cost} <Icons.Diamond className="w-3 h-3 fill-current" />
                                    </button>
                                )}
                            </div>
                        );
                    })}
                </div>

                {/* Number Colors Section */}
                <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-4">Number Styles</h3>
                <div className="grid grid-cols-2 gap-3 mb-8">
                    {NUMBER_COLORS.map(num => {
                        const isOwned = purchasedNumberColors.includes(num.id);
                        const isSelected = selectedNumberColorId === num.id;
                        return (
                            <button 
                                key={num.id}
                                onClick={() => isOwned ? handleSelectNumberColor(num.id) : handleStorePurchase(num, 'num')}
                                className={`bg-t-surface p-4 rounded-2xl shadow-sm border flex flex-col items-center gap-3 transition-all active:scale-[0.98] ${isSelected ? 'border-blue-500 ring-2 ring-blue-500 ring-offset-2 dark:ring-offset-stone-900' : 'border-t-border'}`}
                            >
                                <span className={`text-3xl font-medium ${num.uiClass}`}>5</span>
                                <div className="w-full">
                                    <div className="text-xs font-bold text-t-primary text-center mb-1">{num.name}</div>
                                    {isOwned ? (
                                        isSelected ? (
                                            <div className="text-[10px] font-bold text-blue-500 text-center uppercase tracking-wide">Selected</div>
                                        ) : (
                                            <div className="text-[10px] font-bold text-stone-400 text-center uppercase tracking-wide">Select</div>
                                        )
                                    ) : (
                                        <div className="flex items-center justify-center gap-1 text-xs font-bold text-stone-800 dark:text-stone-200 bg-stone-100 dark:bg-stone-700 py-1 rounded-lg">
                                            {num.cost} <Icons.Diamond className="w-3 h-3 fill-current" />
                                        </div>
                                    )}
                                </div>
                            </button>
                        );
                    })}
                </div>

                {/* Backgrounds Section */}
                <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-4">Atmospheres</h3>
                <div className="grid grid-cols-2 gap-3 mb-8">
                    {ALL_BACKGROUNDS.map(bg => {
                        const isOwned = purchasedBackgrounds.includes(bg.id);
                        const isSelected = selectedBackgroundId === bg.id;
                        return (
                             <button 
                                key={bg.id}
                                onClick={() => isOwned ? handleSelectBackground(bg.id) : handleStorePurchase(bg, 'bg')}
                                className={`bg-t-surface p-2 rounded-2xl shadow-sm border flex flex-col gap-2 transition-all active:scale-[0.98] ${isSelected ? 'border-blue-500 ring-2 ring-blue-500 ring-offset-2 dark:ring-offset-stone-900' : 'border-t-border'}`}
                            >
                                <div className={`w-full aspect-video rounded-xl ${bg.class} relative overflow-hidden`}>
                                    {!isOwned && (
                                        <div className="absolute inset-0 bg-black/10 flex items-center justify-center">
                                            <Icons.Lock className="w-6 h-6 text-white/80" />
                                        </div>
                                    )}
                                </div>
                                <div className="px-1 pb-1 flex items-center justify-between">
                                    <span className="text-xs font-bold text-t-primary">{bg.name}</span>
                                    {isOwned ? (
