                    <div className="flex items-center gap-1 bg-t-surface-sec px-3 py-1.5 rounded-full">
                        <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                        <span className="text-xs font-bold text-t-primary tabular-nums">{points}</span>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto px-6 pb-20 pt-4 w-full flex flex-col items-center">
                    <div className="w-full max-w-md">
                     <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-2xl flex items-center gap-4 mb-8">
                         <div className="w-12 h-12 bg-white dark:bg-blue-800 rounded-full flex items-center justify-center text-blue-500 shadow-sm">
                             <Icons.Video className="w-6 h-6" />
                         </div>
                         <div className="flex-1">
                             <div className="font-bold text-t-primary">Free Gems</div>
                             <div className="text-xs text-t-secondary">Watch a short video</div>
                         </div>
                         <button onClick={handleWatchAd} className="px-4 py-2 bg-blue-500 text-white text-sm font-bold rounded-xl shadow-md active:scale-95 transition">
                             +10 <Icons.Diamond className="w-3 h-3 fill-current inline" />
                         </button>
                     </div>

                     <div className="grid grid-cols-1 gap-4">
                         {DIAMOND_OFFERS.map(offer => {
                             const isStarter = offer.type === 'starter';
                             const isBundle = offer.type === 'bundle';

                             return (
                                 <div 
                                    key={offer.id} 
                                    className={`relative p-5 rounded-3xl border shadow-sm transition-transform active:scale-[0.99] ${
                                        offer.gradientClass 
                                            ? offer.gradientClass 
                                            : 'bg-t-surface border-t-border'
                                    }`}
                                 >
                                     {offer.badge && (
                                         <div className="absolute -top-3 left-6 px-3 py-1 bg-gradient-to-r from-red-500 to-pink-500 text-white text-[10px] font-bold tracking-widest uppercase rounded-full shadow-md">
                                             {offer.badge}
                                         </div>
                                     )}

                                     <div className="flex justify-between items-center mb-3">
                                         <div>
                                             <div className="text-lg font-black tracking-tight">{offer.title}</div>
                                             {offer.subtitle && <div className="text-xs opacity-70 font-medium">{offer.subtitle}</div>}
                                         </div>
                                         <div className="flex flex-col items-end">
                                             <div className="flex items-center gap-1.5">
                                                 <span className="text-2xl font-black">{offer.diamonds}</span>
                                                 <Icons.Diamond className={`w-6 h-6 fill-current ${isStarter || isBundle ? '' : 'text-blue-500'}`} />
                                             </div>
                                         </div>
                                     </div>

                                     {offer.includes && (
                                         <div className="mb-4 space-y-1">
                                             {offer.includes.map((inc, i) => (
                                                 <div key={i} className="flex items-center gap-2 text-xs font-bold opacity-80">
                                                     <div className="w-4 h-4 rounded-full bg-white/50 flex items-center justify-center">
                                                         <Icons.Check className="w-2.5 h-2.5" />
                                                     </div>
                                                     {inc}
                                                 </div>
                                             ))}
                                         </div>
                                     )}

                                     <button onClick={() => handleBuyOffer(offer)} className={`w-full py-3 rounded-xl font-bold text-sm shadow-sm flex items-center justify-center gap-2 ${
                                         isStarter || isBundle 
                                            ? 'bg-stone-900 text-white dark:bg-white dark:text-stone-900' 
                                            : 'bg-blue-600 text-white btn-premium-blue'
                                     }`}>
                                         {offer.priceLabel}
                                     </button>
                                 </div>
                             );
                         })}
                     </div>
                    </div>
                    <div className="h-safe-bottom w-full shrink-0" />
                </div>
          </div>
      )}
      </div>
      </div>
    </div>
  );
}
